/// signature at `sts2-rl-agent@01c094d:sts2_env/core/hooks.py:258-269`.
///
/// `owner` is the creature whose hand played the card (typically the
/// player). `target` is the explicit play target if any. All identity
/// fields default to `None` / empty so legacy `CardPlayCountCtx::default()`
/// callers still produce a valid no-op ctx.
#[derive(Debug, Clone, Copy)]
pub struct CardPlayCountCtx {
    /// Owner side firing the play (typically `CreatureRef::Player`).
    pub owner: CreatureRef,
    /// Stable card identity. `None` for default-ctx callers.
    pub card_id: Option<CardId>,
    /// Per-instance card uid.
    pub card_uid: Option<CardUid>,
    /// Card type discriminant (Attack / Skill / Power / Curse / Status).
    pub card_type: Option<crate::cards::CardType>,
    /// Card tag bitset.
    pub card_tags: CardTags,
    /// Explicit play target if any (Enemy-targeted cards).
    pub target: Option<CreatureUid>,
}

impl Default for CardPlayCountCtx {
    fn default() -> Self {
        Self {
            owner: CreatureRef::Player,
            card_id: None,
            card_uid: None,
            card_type: None,
            card_tags: CardTags::NONE,
            target: None,
        }
    }
}

