    /// `PumpkinCandle.ModifyMaxEnergy → energy + 1` while its
    /// `KindleCount` (mirrored into `Relic.counter`) is `> 0`, on any
    /// act (v0.107.1 C#
    /// `MegaCrit.Sts2.Core.Models.Relics/PumpkinCandle.cs:58-69`).
    /// Bead `sts2-rs-run-rest-option`.
    #[test]
    fn pumpkin_candle_modify_max_energy_kindle_count_gated() {
        let mut state = CombatState::default();
        state.relics.push(Relic {
            id: NonZeroU32::new(42).unwrap(),
            kind: RelicKind::PumpkinCandle,
            counter: 5, // KindleCount = 5 (freshly Rekindled)
            is_wax: false,
            is_melted: false,
        });
        // Bonus applies regardless of act while KindleCount > 0.
        for act in [1_u8, 2, 3] {
            state.act_index = act;
            assert_eq!(
                dispatch_modify_max_energy(&state, &MaxEnergyCtx::default()),
                1,
                "PumpkinCandle: +1 max energy while KindleCount>0 (act={act})",
            );
        }
        // A single remaining kindle still grants the bonus.
        state.relics[0].counter = 1;
        assert_eq!(
            dispatch_modify_max_energy(&state, &MaxEnergyCtx::default()),
            1,
            "PumpkinCandle: +1 max energy at KindleCount=1",
        );
    }

