    /// **v0.107.1 §1a.3 energy-cost "Late" pass equivalence (bead `…wb8lk.1`).**
    /// v0.107.1 threads the cost through the additive non-Late hooks first, then
    /// the absolute-zero Late hooks (Corruption etc.). The accumulator fold
    /// reproduces that: a Skill under BOTH BorrowedTime (additive `+1`, non-Late)
    /// AND Corruption (zero, Late) resolves to 0 — the zero-override always wins
    /// over the surcharge, exactly as "additive pass, then zero pass" computes.
    /// Pins that ordering so a future fold refactor can't resurrect the
    /// surcharge on a zeroed card.
    #[test]
    fn borrowed_time_surcharge_loses_to_corruption_zero() {
        use crate::{Power, PowerKind};

        let mut state = CombatState::default();
        // BorrowedTime: +Amount additive on every owned card (non-Late in C#).
        let bt = NonZeroU32::new(1).unwrap();
        state.powers.push(Power {
            id: bt,
            kind: PowerKind::BorrowedTime,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(bt));
        // Corruption: Skill cost -> 0 (Late in C#).
        let corr = NonZeroU32::new(2).unwrap();
        state.powers.push(Power {
            id: corr,
            kind: PowerKind::Corruption,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(corr));

        // A Skill: BorrowedTime would add +1, Corruption zeroes it. Net 0.
        let skill_ctx = CardCostCtx {
            base_cost: 2,
            card_type: Some(crate::cards::CardType::Skill),
            ..CardCostCtx::default()
        };
        assert_eq!(dispatch_modify_card_cost(&state, &skill_ctx), 0);

        // An Attack: Corruption abstains (Skill-only), only BorrowedTime's +1
        // applies. 2 + 1 = 3.
        let attack_ctx = CardCostCtx {
            base_cost: 2,
            card_type: Some(crate::cards::CardType::Attack),
            ..CardCostCtx::default()
        };
        assert_eq!(dispatch_modify_card_cost(&state, &attack_ctx), 3);
    }

    /// `FreeAttack` zeroes the next Attack's cost while amount > 0.
    /// `FreeSkill` / `FreePower` analogous. Mirrors Python pin
    /// `card_play_effects.py:529/564/599`.
    #[test]
    fn free_powers_zero_their_matching_card_type() {
        use crate::{Power, PowerKind};

        for (kind, ctype) in [
            (PowerKind::FreeAttack, crate::cards::CardType::Attack),
            (PowerKind::FreeSkill, crate::cards::CardType::Skill),
            (PowerKind::FreePower, crate::cards::CardType::Power),
        ] {
            let mut state = CombatState::default();
            let pid = NonZeroU32::new(1).unwrap();
            state.powers.push(Power {
                id: pid,
                kind,
                amount: 1,
                counter: 0,
                applier: None,
                skip_next_tick: false,
            });
            state.player.powers.push(PowerUid(pid));

            let ctx = CardCostCtx {
                base_cost: 2,
                card_type: Some(ctype),
                ..CardCostCtx::default()
            };
            assert_eq!(dispatch_modify_card_cost(&state, &ctx), 0);

            // Amount = 0 → arm abstains.
            if let Some(power) = state.powers.get_mut_by_id(pid) {
                power.amount = 0;
            }
            assert_eq!(dispatch_modify_card_cost(&state, &ctx), 2);
        }
    }

    /// Bead `sts2-rs-g0gs9`: Tangled adds `+amount` to Attack cards
    /// (additive, not an override), abstains on non-Attack cards, and
    /// composes additively across stacks. Mirrors C#
    /// `TangledPower.TryModifyEnergyCostInCombat` (`originalCost + Amount`).
    #[test]
    fn tangled_surcharges_attack_cost_additively() {
        use crate::cards::CardType;
        use crate::{Power, PowerKind};

        let mut state = CombatState::default();
        let pid = NonZeroU32::new(1).unwrap();
        state.powers.push(Power {
            id: pid,
            kind: PowerKind::Tangled,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(pid));

        // Attack: base 1 + Tangled(1) = 2.
        let attack_ctx = CardCostCtx {
            base_cost: 1,
            card_type: Some(CardType::Attack),
            ..CardCostCtx::default()
        };
        assert_eq!(dispatch_modify_card_cost(&state, &attack_ctx), 2);

        // Skill: untouched (Tangled only afflicts Attack cards).
        let skill_ctx = CardCostCtx {
            base_cost: 1,
            card_type: Some(CardType::Skill),
            ..CardCostCtx::default()
        };
        assert_eq!(dispatch_modify_card_cost(&state, &skill_ctx), 1);

        // amount=2 → +2 surcharge.
        if let Some(power) = state.powers.get_mut_by_id(pid) {
            power.amount = 2;
        }
        assert_eq!(dispatch_modify_card_cost(&state, &attack_ctx), 3);
    }

