    /// Smoke-test: every per-category dispatcher compiles, runs against
    /// a default state with one power + one relic, and returns its
    /// expected no-op aggregate. This is the Option-B equivalent of an
    /// "exhaustiveness" check — touching one dispatcher per `HookId`
    /// variant guarantees adding a new variant is a compile-time TODO
    /// (no fn yet exists for it). The `HookId::ALL` length is asserted
    /// to match the dispatcher count we touch.
    #[test]
    fn dispatch_compiles_for_all_hookids() {
        // Sum of dispatcher counts grouped by HookId category. The HP-loss
        // category contributes THREE dispatchers (additive / multiplicative /
        // cap — Rust-side decomposition for the single-floor invariant; bead
        // sts2-rs-nj8) even though `HookId::ModifyHpLost` is a single variant
        // (Python's listener method name is also single). The total exceeds
        // `HookId::COUNT` by exactly 2 — the HP-loss split. Hoisted up here
        // to avoid `clippy::items_after_statements`.
        // Bead `sts2-rs-47jv` adds 5 new dispatchers for the C#-canon
        // `modify_power_amount_*` channel family (inserted between
        // power-application gating and hand-draw modifiers below).
        const TOUCHED_DISPATCHERS: usize =
            6 + 2 + 5 + 3 + 1 + 2 + 5 + 3 + 2 + 1 + 5 + 5 + 6 + 1 + 7 + 1 + 1 + 1;
        const HP_LOSS_DISPATCHER_SPLIT: usize = 2;

        let mut state = CombatState::default();
        state.player.powers.push(power_uid(1));
        state.relics.push(Relic {
            id: NonZeroU32::new(1).unwrap(),
            kind: RelicKind::BurningBlood,
            counter: 0,
            is_wax: false,
            is_melted: false,
        });

        // Damage pipeline (6 hooks).
        assert_eq!(
            dispatch_modify_damage_additive(&state, &DamageCtx::default()),
            0
        );
        // Multiplicative no-op default is `DamageMul::ONE`; composing 2
        // listeners' identity rationals yields ONE.
        assert_eq!(
            dispatch_modify_damage_multiplicative(&state, &DamageCtx::default()),
            DamageMul::ONE
        );
        assert_eq!(
            dispatch_modify_damage_cap(&state, &DamageCtx::default()),
            i32::MAX
        );
        // P2-2b sts2-rs-3to: before/after_damage_received now take &mut state
        // (collect-and-drain effect queue).
        dispatch_before_damage_received(&mut state, &DamageCtx::default());
        dispatch_after_damage_received(&mut state, &DamageCtx::default(), 0);
        // Bead `sts2-rs-zlx.3`: dispatch_after_damage_given now takes
        // &mut state + a damage parameter to feed the Envenom arm.
        dispatch_after_damage_given(&mut state, &DamageCtx::default(), 0, 0, false);

        // Attack events (2).
        dispatch_before_attack(&state, &AttackCtx::default());
        dispatch_after_attack(&state, &AttackCtx::default());

        // Block pipeline (5).
        assert_eq!(
            dispatch_modify_block_additive(&state, &BlockCtx::default()),
            0
        );
        assert_eq!(
            dispatch_modify_block_multiplicative(&state, &BlockCtx::default()),
            DamageMul::ONE
        );
        dispatch_after_block_gained(&mut state, &BlockGainedCtx::default());
        dispatch_after_block_cleared(&mut state, &BlockClearedCtx::default());
        // Default `should_clear_block` returns true → dispatcher returns true.
        assert!(dispatch_should_clear_block(
            &state,
            &BlockClearedCtx::default()
        ));

        // HP loss (3 — additive / multiplicative / cap; bead sts2-rs-nj8).
        assert_eq!(
            dispatch_modify_hp_lost_additive(&state, &HpLostCtx::default()),
            0
        );
        assert_eq!(
            dispatch_modify_hp_lost_multiplicative(&state, &HpLostCtx::default()),
            DamageMul::ONE
        );
        assert_eq!(
            dispatch_modify_hp_lost_cap(&state, &HpLostCtx::default()),
            i32::MAX
        );
        // Top-level pipeline: 0 listeners → identity (0).
        assert_eq!(modify_hp_lost(&state, 0, &HpLostCtx::default()), 0);

        // Power-application gating (1, powers-only).
        // P2-2b sts2-rs-3to: dispatch_try_block_debuff now takes &mut state.
        assert!(!dispatch_try_block_debuff(
            &mut state,
            &TryBlockDebuffCtx::default()
        ));

        // Hand-draw / energy modifiers (2).
        assert_eq!(
            dispatch_modify_hand_draw(&state, &HandDrawCtx::default()),
            0
        );
        assert_eq!(
            dispatch_modify_max_energy(&state, &MaxEnergyCtx::default()),
            0
        );

        // Summon (3).
        assert_eq!(
            dispatch_modify_summon_amount(&state, &SummonAmountCtx::default()),
            0
        );
        dispatch_after_summon(&state, &SummonCtx::default());
        dispatch_after_osty_revived(&state, &OstyRevivedCtx::default());

        // Card play count (2).
        assert_eq!(
            dispatch_modify_card_play_count(&state, &CardPlayCountCtx::default()),
            0
        );
        dispatch_after_modifying_card_play_count(&mut state, &CardCtx::default());

        // Card cost (1; bead sts2-rs-zlx.5). Default ctx has
        // base_cost = 0 so the dispatcher returns 0 with no listeners
        // wired for the registered player power + BurningBlood relic.
        assert_eq!(
            dispatch_modify_card_cost(&state, &CardCostCtx::default()),
            0
        );

        // Should-X predicates (5).
        assert!(dispatch_should_reset_energy(
            &state,
            &CombatLifecycleCtx::default()
        ));
        assert!(dispatch_should_flush(
            &state,
            &CombatLifecycleCtx::default()
        ));
        assert!(dispatch_should_play(&state, &CardCtx::default()));
        assert!(dispatch_should_draw(&state, &DrawCtx::default()));
        assert!(!dispatch_should_take_extra_turn(
            &state,
            &CombatLifecycleCtx::default()
        ));

        // Card events (5).
        dispatch_before_card_played(&state, &CardCtx::default());
        // Bead `sts2-rs-zlx.3`: dispatch_after_card_played now takes
        // &mut state to apply Rage/Afterimage/PhantomBlades listener
        // bodies after the walk.
        dispatch_after_card_played(&mut state, &CardCtx::default());
        // Bead `sts2-rs-zlx.1`: dispatch_after_card_exhausted now takes
        // &mut state to apply FNP/DE listener bodies after the walk.
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);
        // Bead `sts2-rs-ymlf`: dispatch_after_card_discarded now takes
        // &mut state to apply Reflex's on-discard "draw 2" body after
        // the walk.
        dispatch_after_card_discarded(&mut state, &CardCtx::default());
        dispatch_on_card_drawn(&state, &CardDrawnCtx::default());

        // Turn boundary (5; the no-op `on_turn_start_own_side` walk is gone).
        // sts2-rs-rnv6: dispatch_before_turn_end now takes &mut state.
        dispatch_before_turn_end(&mut state, &TurnSideCtx::default());
        // P3-6 sts2-rs-p1n: dispatch_after_turn_end + dispatch_on_turn_end_enemy_side
        // now take &mut state to drain the deferred-effect queue.
        dispatch_after_turn_end(&mut state, &TurnSideCtx::default());
        dispatch_on_turn_end_enemy_side(&mut state, &TurnSelfCtx::default());
        // sts2-rs-6ynt.6.8: dispatch_before_side_turn_start now takes &mut state.
        dispatch_before_side_turn_start(&mut state, &TurnSideCtx::default());
        // P2-2b sts2-rs-3to: dispatch_after_side_turn_start now takes &mut state.
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx::default());

        // Creature lifecycle (1).
        dispatch_after_creature_added_to_combat(&state, &CreatureAddedCtx::default());

        // Combat lifecycle (7).
        dispatch_before_combat_start(&state, &CombatLifecycleCtx::default());
        dispatch_after_combat_victory(&state, &CombatLifecycleCtx::default());
        dispatch_after_combat_end(&state, &CombatLifecycleCtx::default());
        dispatch_after_taking_extra_turn(&state, &CombatLifecycleCtx::default());
        dispatch_after_energy_reset(&mut state, &CombatLifecycleCtx::default());
        dispatch_after_shuffle(&mut state, &CombatLifecycleCtx::default());
        dispatch_after_hand_emptied(&state, &CombatLifecycleCtx::default());

        // Orb events (1, bead sts2-rs-1h8q ch.5).
        dispatch_on_orb_channeled(&state, &OrbChanneledCtx::default());

        // Stars events (1, bead sts2-rs-nrjb ch.6).
        dispatch_on_stars_spent(&state, &StarsSpentCtx::default());

        // Misc (1).
        dispatch_after_forge(&state, &ForgeCtx::default());

        // Sanity: `HookId::ALL` length matches Python's listener-method
        // count (48 post-zlx.5); the touched dispatchers exceed it by the
        // HP-loss split (additive + multiplicative + cap = 3 dispatchers
        // vs 1 HookId). 6+2+5+3+1+2+3+2+1+5+5+6+1+7+1 = 50 = 48 + 2.
        assert_eq!(
            TOUCHED_DISPATCHERS,
            HookId::COUNT + HP_LOSS_DISPATCHER_SPLIT
        );
        assert_eq!(HookId::ALL.len(), HookId::COUNT);
    }

    // -----------------------------------------------------------------
    // P2-1 sts2-rs-58w: damage and block hook chains.
    //
    // These tests lock the pipeline order, the single-floor invariant,
    // and the per-dispatcher aggregation primitives that Python relies
    // on. Per-listener match-arm bodies (Vulnerable, Weak, Strength,
    // Dexterity, ...) land in bead sts2-rs-6w8 (P2-2) and are out of
    // scope here.
    // -----------------------------------------------------------------

    /// `DamageMul::apply` matches `math.floor(x * (num as f64) / (den as f64))`
    /// over `[-100, 100]` for a representative cross-section of the
    /// rationals enumerated in the multiplier-rounding audit. This is
    /// the Phase 2 acceptance test for the rational composer (audit
    /// §"Recommendations for Phase 2 implementation" item 4).
    #[test]
    fn damage_mul_apply_matches_python_floor() {
        let cases: &[(DamageMul, &str)] = &[
            (DamageMul::VULNERABLE, "vulnerable 1.5"),
            (DamageMul::WEAK, "weak 0.75"),
            (DamageMul::FRAIL, "frail 0.75"),
            (DamageMul::HALF, "half 0.5"),
            (DamageMul::DOUBLE, "double 2.0"),
            (DamageMul::TRIPLE, "triple 3.0"),
            (DamageMul::ZERO, "zero 0.0"),
            (DamageMul::new(7, 4), "vuln+cruelty25 1.75"),
            (DamageMul::new(125, 100), "lethality25 1.25"),
            (DamageMul::new(13, 10), "slow stack=3 1.3"),
        ];
        for (mul, label) in cases {
            for x in -100..=100i32 {
                #[allow(clippy::cast_precision_loss)]
                let f = f64::from(x) * (mul.num as f64) / (mul.den as f64);
                #[allow(clippy::cast_possible_truncation)]
                let py = f.floor() as i32;
                let rs = mul.apply(x);
                assert_eq!(
                    rs, py,
                    "{label}: x={x}, num={}, den={}, py={py}, rs={rs}",
                    mul.num, mul.den
                );
            }
        }
    }

    /// `apply_frac` floors a RATIONAL base once at the end — the Thrash
    /// decimal-fold invariant (bead `sts2-rs-thrash-decimal`). It must equal
    /// `apply` for integer bases (`den == 1`), and for a fractional base it
    /// must floor `base × mul` ONCE (not floor the base first): the canonical
    /// case is `BaseValue 8.9` under Shrink `0.7` → `floor(8.9×0.7)=6`, where
    /// flooring the base first gives `floor(8×0.7)=5`.
    #[test]
    fn damage_mul_apply_frac_floors_once() {
        // Integer base (den 1) agrees with `apply` over a range of multipliers.
        for mul in [
            DamageMul::SHRINK,
            DamageMul::WEAK,
            DamageMul::VULNERABLE,
            DamageMul::new(7, 4),
        ] {
            for x in -50..=50i64 {
                assert_eq!(
                    mul.apply_frac(x, 1),
                    mul.apply(x as i32),
                    "den-1 frac must equal apply: x={x}, mul={}/{}",
                    mul.num,
                    mul.den
                );
            }
        }
        // BaseValue 8.9 (= 89/10) under Shrink 0.7 → floor(6.23) = 6, NOT
        // floor(floor(8.9)×0.7) = floor(5.6) = 5.
        assert_eq!(DamageMul::SHRINK.apply_frac(89, 10), 6);
        assert_eq!(DamageMul::SHRINK.apply(8), 5);
        // Same base under Vulnerable 1.5 → floor(8.9×1.5)=floor(13.35)=13.
        assert_eq!(DamageMul::VULNERABLE.apply_frac(89, 10), 13);
        // Identity multiplier just floors the rational: floor(8.9) = 8.
        assert_eq!(DamageMul::ONE.apply_frac(89, 10), 8);
    }

    /// `compose` is associative and commutative on the integer result
    /// after a single floor-at-end. Walks two non-trivial rationals in
    /// both orders and confirms the output integer matches.
    #[test]
    fn damage_mul_compose_is_order_invariant_after_floor() {
        let v = DamageMul::VULNERABLE; // 3/2
        let w = DamageMul::WEAK; // 3/4
        for x in 0..=200i32 {
            let v_then_w = v.compose(w).apply(x);
            let w_then_v = w.compose(v).apply(x);
            assert_eq!(v_then_w, w_then_v, "order matters at x={x}");
        }
    }

    /// **Damage pipeline order:** additive applied **before** multiplicative
    /// (matches `hooks.py:79-89` step 1 then step 2). We can't yet wire a
    /// power that contributes additive 5 + a separate one that contributes
    /// multiplicative 1.5x (that's bead sts2-rs-6w8), so we directly
    /// compose the dispatcher outputs the way `modify_damage` does and
    /// assert the result equals `floor((base + add) * mul)` not
    /// `floor(base * mul) + add`.
    #[test]
    fn damage_pipeline_order_matches_python() {
        let state = CombatState::default();
        let ctx = DamageCtx::default();
        // No listeners yet → additive=0, mul=ONE → modify_damage(base) == base.
        assert_eq!(modify_damage(&state, 7, &ctx), 7);

        // Manual order check: simulate +5 additive + 1.5x mul on base=10.
        // Correct (Python): floor((10+5)*1.5) = 22.
        // Wrong (mul-then-add): floor(10*1.5)+5 = 20.
        // The pipeline order is encoded in `modify_damage` itself; this
        // test re-derives the math against `DamageMul::apply` so adding a
        // listener body in 6w8 that returns 5 + VULNERABLE produces the
        // 22 result, not 20.
        let base = 10i32;
        let additive = 5i32;
        let mul = DamageMul::VULNERABLE;
        let correct = mul.apply(base + additive); // matches modify_damage
        let wrong = mul.apply(base) + additive; // mul-then-add
        assert_eq!(correct, 22);
        assert_eq!(wrong, 20);
        assert_ne!(correct, wrong);
    }

    /// **Single-floor invariant:** the canonical divergent fixture from
    /// the audit `(1*1.5).floor()*0.75).floor() = 0` vs
    /// `floor(1*1.5*0.75) = 1` must produce the Python answer (1) — i.e.
    /// our pipeline must compose rationals before flooring.
    #[test]
    fn damage_pipeline_floors_once_at_end() {
        // Composed rational: 3/2 * 3/4 = 9/8.
        let composed = DamageMul::VULNERABLE.compose(DamageMul::WEAK);
        assert_eq!(composed.num, 9);
        assert_eq!(composed.den, 8);

        // Single-floor result on x=1: floor(1 * 9/8) = floor(1.125) = 1.
        assert_eq!(composed.apply(1), 1);

        // Per-stage floor (the bug we're guarding against):
        // floor(1 * 1.5) = 1 → floor(1 * 0.75) = 0.
        let buggy = DamageMul::VULNERABLE.apply(1);
        let buggy_then_weak = DamageMul::WEAK.apply(buggy);
        assert_eq!(buggy_then_weak, 0);

        // The pipeline composes-then-floors-once → matches Python.
        assert_ne!(composed.apply(1), buggy_then_weak);

        // Audit §"Multi-stage pipeline" claims 125/1000 inputs diverge
        // for this two-stage chain. Verify at least one mismatch in the
        // first 16 inputs to lock the property:
        let mismatches = (0..1000)
            .filter(|x| {
                let single = composed.apply(*x);
                let staged = DamageMul::WEAK.apply(DamageMul::VULNERABLE.apply(*x));
                single != staged
            })
            .count();
        assert_eq!(
            mismatches, 125,
            "audit claims 125 divergences in [0, 999]; found {mismatches}"
        );
    }

    /// **Block pipeline order:** same shape as damage (additive before
    /// multiplicative). Block has no cap pass — `modify_block` does not
    /// call `dispatch_modify_block_cap` (Python `hooks.py:125-157` has
    /// no cap step).
    #[test]
    fn block_pipeline_order_matches_python() {
        let state = CombatState::default();
        let ctx = BlockCtx::default();
        assert_eq!(modify_block(&state, 7, &ctx), 7);

        // Frail (0.75x) on 10+5 base: floor((10+5)*0.75) = 11.
        // Wrong (mul-then-add): floor(10*0.75)+5 = 12.
        let base = 10i32;
        let additive = 5i32;
        let mul = DamageMul::FRAIL;
        let correct = mul.apply(base + additive);
        let wrong = mul.apply(base) + additive;
        assert_eq!(correct, 11);
        assert_eq!(wrong, 12);
        assert_ne!(correct, wrong);
    }

    /// **Block clamps at zero**: `modify_block` returns `max(0, ...)`,
    /// so a NoBlock-like rational of `0/1` produces 0 not negative.
    #[test]
    fn block_pipeline_clamps_at_zero() {
        let state = CombatState::default();
        let ctx = BlockCtx::default();
        // No listener bodies yet, but verify the clamp directly via the
        // composer — `DamageMul::ZERO.apply(50) = 0`.
        assert_eq!(DamageMul::ZERO.apply(50), 0);
        // And the pipeline preserves the clamp:
        assert_eq!(modify_block(&state, 0, &ctx), 0);
        assert_eq!(modify_block(&state, -5, &ctx).max(0), 0);
    }

    /// Bead `sts2-rs-44dht`: `PowerAmountCtx::new(applier, target,
    /// power_kind, amount)` — 4 positional args set the 4 named
    /// fields; `source_card` is hardcoded to None. A regression that
    /// swapped `applier` and `target` (both involve CreatureRef-shaped
    /// types) would compile cleanly and silently break listener
    /// guards that gate on "owner is creature" (e.g. GrapplePower's
    /// owner-targeted block check). Locks the field-wiring contract.
    #[test]
    fn power_amount_ctx_new_wires_fields_in_correct_order() {
        let applier = Some(CreatureRef::Player);
        let target = CreatureRef::Ally(2);
        let ctx = PowerAmountCtx::new(applier, target, PowerKind::Strength, 7);
        assert_eq!(ctx.applier, applier, "applier slot");
        assert_eq!(ctx.target, target, "target slot");
        assert_eq!(ctx.power_kind, PowerKind::Strength, "power_kind slot");
        assert_eq!(ctx.amount, 7, "amount slot");
        assert!(
            ctx.source_card.is_none(),
            "source_card defaults to None at the new() constructor"
        );
        // Swap arms: a None applier must NOT bleed into target. Locks the
        // distinct origin/destination of the two CreatureRef-shaped args.
        let ctx_none_applier = PowerAmountCtx::new(None, target, PowerKind::Vulnerable, 0);
        assert_eq!(ctx_none_applier.applier, None);
        assert_eq!(ctx_none_applier.target, target);
    }

    /// Bead `sts2-rs-r5lbi`: `effective_card_cost` short-circuits to
    /// 0 when the card's per-instance `VarKey::FreeThisTurn != 0`,
    /// BEFORE the `modify_card_cost` listener walk (hooks.rs:4767,
    /// bead c68o, InfernalBlade rider). A regression that moved the
    /// rider check after the listener walk would silently break the
    /// rider when no listener returned a Some lower than base_cost.
    #[test]
    fn effective_card_cost_freethisturn_rider_short_circuits_to_zero() {
        use crate::cards::{CardId, CardTags, CardType, TargetType, VarKey};
        let mut state = CombatState::default();
        let uid = crate::CardUid::new(1).expect("non-zero");
        state.cards.push(crate::Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 3,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        // Baseline: no rider → effective cost is the base (no listeners).
        assert_eq!(effective_card_cost(&state, uid), 3);
        // Flip the FreeThisTurn rider. The rider check fires before the
        // listener walk, so the result is 0 regardless of base_cost.
        state.cards[0].set_combat_var(VarKey::FreeThisTurn, 1);
        assert_eq!(effective_card_cost(&state, uid), 0);
        // Clear the rider — cost returns to base.
        state.cards[0].set_combat_var(VarKey::FreeThisTurn, 0);
        assert_eq!(effective_card_cost(&state, uid), 3);
    }

    /// Bead `sts2-rs-flatten-osty-cost`: FLATTEN (Necrobinder, base 2)
    /// costs 0 for the rest of the turn once the Osty has attacked this
    /// turn (C# `Flatten` reactive `SetThisTurn(0)`), modeled via the
    /// monotonic `CombatLog::osty_attacks_this_turn`. Parity Necro
    /// PARITY10: an over-charged FLATTEN cascaded into an energy / hand /
    /// enemy-hp divergence.
    #[test]
    fn effective_card_cost_flatten_is_zero_after_osty_attacked_this_turn() {
        use crate::cards::{CardId, CardTags, CardType, TargetType};
        let mut state = CombatState::default();
        let uid = crate::CardUid::new(1).expect("non-zero");
        state.cards.push(crate::Card {
            uid,
            card_id: CardId::Flatten,
            cost: 2,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 12,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        // No Osty attack yet this turn → full base cost.
        assert_eq!(state.combat_log.osty_attacks_this_turn, 0);
        assert_eq!(effective_card_cost(&state, uid), 2);
        // Osty has attacked → FLATTEN is free for the rest of the turn.
        state.combat_log.osty_attacks_this_turn = 1;
        assert_eq!(effective_card_cost(&state, uid), 0);
        // Turn-start reset of the counter restores the base cost.
        state.combat_log.osty_attacks_this_turn = 0;
        assert_eq!(effective_card_cost(&state, uid), 2);
    }

    /// GH #742: C# `SpikedGauntlets.TryModifyEnergyCostInCombat` adds 1 to the
    /// owner's Power cards in the EARLY pass, after the creature powers
    /// (`CombatState.IterateHookListeners` yields powers before relics):
    /// - Curious (early power, floors at 0) runs first: a 1-cost Power under
    ///   Curious 2 is `max(0, 1 - 2) + 1 = 1`, not `max(0, 1 - 2 + 1) = 0`.
    /// - FreePower is a LATE hook, so it still zeroes the card.
    /// - X-cost and negative-cost cards skip the global hooks entirely.
    #[test]
    fn spiked_gauntlets_adds_one_to_power_cards_after_powers_before_late_overrides() {
        use crate::cards::{CardId, CardTags, CardType, TargetType};
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 70;
        state.init_player_creature();
        state.relics.push(crate::Relic {
            id: std::num::NonZeroU32::new(1).expect("nz"),
            kind: crate::RelicKind::SpikedGauntlets,
            counter: 0,
            is_wax: false,
            is_melted: false,
        });
        let mk = |raw: u32, card_id, cost, card_type| crate::Card {
            uid: crate::CardUid::new(raw).expect("non-zero"),
            card_id,
            cost,
            card_type,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        };
        let power = mk(1, CardId::Inflame, 1, CardType::Power);
        let attack = mk(2, CardId::StrikeIronclad, 1, CardType::Attack);
        let x_power = mk(3, CardId::Inflame, -1, CardType::Power);
        for c in [power, attack, x_power] {
            state.cards.push(c);
        }
        assert_eq!(effective_card_cost(&state, power.uid), 2);
        assert_eq!(effective_card_cost(&state, attack.uid), 1);
        assert_eq!(effective_card_cost(&state, x_power.uid), 0);

        let player = state.player.creature_uid.expect("player creature");
        crate::card_effects::apply_power_to_creature(&mut state, player, PowerKind::Curious, 2);
        assert_eq!(effective_card_cost(&state, power.uid), 1);
        assert_eq!(effective_card_cost(&state, x_power.uid), 0);

        crate::card_effects::apply_power_to_creature(&mut state, player, PowerKind::FreePower, 1);
        assert_eq!(effective_card_cost(&state, power.uid), 0);
    }

    /// C# `CuriousPower.TryModifyEnergyCostInCombat`
    /// (`../sts2-wiki/decompiled/v0.107.1/MegaCrit.Sts2.Core.Models.Powers/CuriousPower.cs:12-33`):
    /// owner-owned **Power** cards with `originalCost > 0` cost
    /// `originalCost - Amount`, floored at 0. Attacks/Skills and already-free
    /// cards are untouched. Applied by MadScience's `Curious` rider
    /// (`MadScience.cs:241-243`). Before this arm existed `PowerKind::Curious`
    /// had no entry in `modify_card_cost` at all, so the mirror charged full
    /// price for every Power card and ran exactly 1 energy low.
    #[test]
    fn curious_reduces_power_card_cost_only() {
        use crate::cards::{CardId, CardTags, CardType, TargetType};
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 70;
        state.init_player_creature();

        let power_uid = crate::CardUid::new(1).expect("non-zero");
        let attack_uid = crate::CardUid::new(2).expect("non-zero");
        let free_power_uid = crate::CardUid::new(3).expect("non-zero");
        let mk = |uid, card_id, cost, card_type| crate::Card {
            uid,
            card_id,
            cost,
            card_type,
            target_type: TargetType::Self_,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        };
        state
            .cards
            .push(mk(power_uid, CardId::Inflame, 1, CardType::Power));
        state
            .cards
            .push(mk(attack_uid, CardId::StrikeIronclad, 1, CardType::Attack));
        state
            .cards
            .push(mk(free_power_uid, CardId::Inflame, 0, CardType::Power));

        // Baseline (no Curious): everything at face value.
        assert_eq!(effective_card_cost(&state, power_uid), 1);
        assert_eq!(effective_card_cost(&state, attack_uid), 1);
        assert_eq!(effective_card_cost(&state, free_power_uid), 0);

        let player = state.player.creature_uid.expect("player creature");
        crate::card_effects::apply_power_to_creature(&mut state, player, PowerKind::Curious, 1);

        // Power card: 1 - 1 = 0 (C# clamps at 0, so no negative cost).
        assert_eq!(effective_card_cost(&state, power_uid), 0);
        // `card.Type != CardType.Power` → the Attack is untouched.
        assert_eq!(effective_card_cost(&state, attack_uid), 1);
        // `originalCost <= 0m` → an already-free Power is untouched.
        assert_eq!(effective_card_cost(&state, free_power_uid), 0);

        // Amount 2 on a 1-cost Power still floors at 0, never -1.
        crate::card_effects::apply_power_to_creature(&mut state, player, PowerKind::Curious, 1);
        assert_eq!(
            state
                .powers
                .iter()
                .find(|p| p.kind == PowerKind::Curious)
                .map_or(0, |p| p.amount),
            2
        );
        assert_eq!(effective_card_cost(&state, power_uid), 0);
    }

    /// Bead `sts2-rs-7ggdl`: `effective_card_cost` is a total helper
    /// — the comment at hooks.rs:4749-4751 says "callers should always
    /// pass a uid drawn from a live pile; the fallback keeps the helper
    /// total." The defensive `let Some(card) = state.cards.get(idx)
    /// else { return 0; }` at line 4756 enforces that. A drive-by
    /// swapping `.get(idx)` for index-by-bracket would silently turn a
    /// helper-total invariant into a panic.
    #[test]
    fn effective_card_cost_returns_zero_for_out_of_range_uid() {
        let state = CombatState::default();
        // state.cards is empty in a default CombatState — any uid resolves
        // out-of-range. Pick a deliberately-high uid to make the
        // out-of-range nature obvious in failure output.
        let oob_uid = crate::CardUid::new(99_999).expect("non-zero uid");
        assert_eq!(
            effective_card_cost(&state, oob_uid),
            0,
            "out-of-range card_uid must return 0, not panic"
        );
    }

    /// Bead `sts2-rs-5x2ng`: `dispatch_modify_summon_amount` and
    /// `dispatch_modify_card_play_count` are saturating-additive folds
