    /// Bead `sts2-rs-2b25o`: `DamageMul` named constants are pinned
    /// to specific (num, den) values per
    /// `docs/multiplier-rounding-audit.md` and the Python source.
    /// A typo (e.g. FRAIL = 3/5 instead of 3/4) would silently
    /// diverge from Python parity. WEAK == FRAIL by design (both
    /// 3/4, kept distinct for call-site readability per the
    /// comment at line 105).
    #[test]
    fn damage_mul_named_constants_match_audit() {
        assert_eq!((DamageMul::ONE.num, DamageMul::ONE.den), (1, 1));
        assert_eq!(
            (DamageMul::VULNERABLE.num, DamageMul::VULNERABLE.den),
            (3, 2)
        );
        assert_eq!((DamageMul::WEAK.num, DamageMul::WEAK.den), (3, 4));
        assert_eq!((DamageMul::FRAIL.num, DamageMul::FRAIL.den), (3, 4));
        assert_eq!((DamageMul::HALF.num, DamageMul::HALF.den), (1, 2));
        assert_eq!((DamageMul::DOUBLE.num, DamageMul::DOUBLE.den), (2, 1));
        assert_eq!((DamageMul::TRIPLE.num, DamageMul::TRIPLE.den), (3, 1));
        assert_eq!((DamageMul::ZERO.num, DamageMul::ZERO.den), (0, 1));
        // WEAK and FRAIL are bit-identical by design — locks the
        // "kept distinct for readability, not for numeric divergence"
        // comment at line 105.
        assert_eq!(DamageMul::WEAK, DamageMul::FRAIL);
    }

    /// Bead `sts2-rs-pm6rf`: `DamageMul::new(num, den)` field-wiring
    /// + ZERO composition absorption. A swap of num/den would compile
    /// cleanly (both i64) and silently produce reciprocal multipliers.
    /// ZERO.compose(X) is the absorption element — covered indirectly
    /// via apply-matches-python-floor, but no direct compose-absorption
    /// test exists.
    #[test]
    fn damage_mul_new_field_wiring_and_zero_composition_absorption() {
        // Field-wiring: positional args land in the correct slots.
        let m = DamageMul::new(3, 7);
        assert_eq!(m.num, 3, "first arg lands in num");
        assert_eq!(m.den, 7, "second arg lands in den");

        // ZERO absorption — ZERO.compose(any) yields a rational whose
        // num is 0 (the i64 multiplication 0 * other.num = 0). Apply
        // of any composed result is 0.
        for r in [
            DamageMul::ONE,
            DamageMul::VULNERABLE,
            DamageMul::DOUBLE,
            DamageMul::TRIPLE,
            DamageMul::new(7, 4),
        ] {
            let composed = DamageMul::ZERO.compose(r);
            assert_eq!(composed.num, 0, "ZERO.compose(r).num = 0");
            for x in [-50, -1, 0, 1, 50] {
                assert_eq!(composed.apply(x), 0, "ZERO absorbs apply({x})");
            }
            // Symmetric — r.compose(ZERO) also absorbs.
            let composed_rev = r.compose(DamageMul::ZERO);
            assert_eq!(composed_rev.num, 0);
            assert_eq!(composed_rev.apply(50), 0);
        }
    }

    /// **`DamageMul::ONE` is the multiplicative identity**: composing
    /// ONE with any rational yields the same rational (up to numeric
    /// equivalence on `apply`).
    #[test]
    fn damage_mul_one_is_identity() {
        let rationals = [
            DamageMul::VULNERABLE,
            DamageMul::WEAK,
            DamageMul::HALF,
            DamageMul::DOUBLE,
            DamageMul::ZERO,
        ];
        for r in &rationals {
            for x in -50..=50i32 {
                assert_eq!(DamageMul::ONE.compose(*r).apply(x), r.apply(x));
                assert_eq!(r.compose(DamageMul::ONE).apply(x), r.apply(x));
            }
        }
    }

    // -----------------------------------------------------------------
    // P2-2 sts2-rs-6w8: 10 core player powers.
    //
    // Per-power dispatcher tests. Each test attaches a single power to
    // the primary player (or a fabricated enemy creature) and asserts
    // the dispatcher returns the expected per-Python rational / scalar.
    // Pipeline-order tests (Strength + Vulnerable composition) live in
    // P2-1's existing `damage_pipeline_*` tests.
    // -----------------------------------------------------------------

    use crate::{Power, PowerKind};

    /// Attach a single `Power { kind, amount }` to the primary player.
    /// Returns the state plus the `PowerUid`.
    fn state_with_player_power(kind: PowerKind, amount: i32) -> (CombatState, PowerUid) {
        let mut state = CombatState::default();
        let uid = power_uid(1);
        state.powers.push(Power {
            id: uid.0,
            kind,
            amount,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(uid);
        (state, uid)
    }

    /// **Strength:** `modify_damage_additive` returns `+amount` only when
    /// `dealer == owner` AND `props.is_powered()` (P2-2c sts2-rs-v7d). With
    /// Strength(3) on the player + a powered attack from the player, raw
    /// damage 5 becomes 8. Mirrors Python
    /// `sts2_env/powers/common.py::StrengthPower.modify_damage_additive`.
    #[test]
    fn strength_adds_to_player_damage() {
        let (state, _) = state_with_player_power(PowerKind::Strength, 3);
        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: CreatureRef::Enemy(CreatureUid::new(99).unwrap()),
            props: ValueProps::MOVE,
        };
        assert_eq!(dispatch_modify_damage_additive(&state, &ctx), 3);
        // Pipeline: floor((5 + 3) * 1) = 8.
        assert_eq!(modify_damage(&state, 5, &ctx), 8);
    }

    /// Bead `sts2-rs-q6bix` (F-S): `BlockNextTurnPower.AfterBlockCleared`
    /// (Ship in a Bottle potion). When the owner's block is cleared, gain
    /// `Amount` block (Unpowered) and remove the power. C#
    /// `BlockNextTurnPower.cs`: `if creature == Owner { GainBlock(Owner,
    /// Amount, Unpowered); Remove(this); }`.
    #[test]
    fn block_next_turn_gains_block_and_self_removes_on_clear() {
        let (mut state, _uid) = state_with_player_power(PowerKind::BlockNextTurn, 10);
        assert_eq!(state.player.block, 0);
        // The player's own turn-start clear tags `cleared = Player`, which
        // the owner-scoped arm requires (C# gates `creature == Owner`).
        dispatch_after_block_cleared(
            &mut state,
            &BlockClearedCtx {
                cleared: Some(CreatureRef::Player),
            },
        );
        assert_eq!(
            state.player.block, 10,
            "BlockNextTurn grants its amount as block when block clears"
        );
        assert!(
            !state
                .player
                .powers
                .iter()
                .any(|p| state.powers.iter().any(|pw| pw.id == p.0)),
            "BlockNextTurn removes itself after firing"
        );
    }

    /// Bead `sts2-rs-63mew`: minimal card POD for the Stratagem
    /// `after_shuffle` tests below.
    fn push_test_card(state: &mut CombatState, raw: u32, card_id: crate::cards::CardId) -> CardUid {
        let uid = CardUid::new(raw).expect("non-zero");
        state.cards.push(crate::Card {
            uid,
            card_id,
            cost: 1,
            card_type: crate::cards::CardType::Attack,
            target_type: crate::cards::TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: crate::cards::CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        uid
    }

    /// Bead `sts2-rs-63mew`: a reshuffle during a hand draw with a
    /// Stratagem stack fires the power-side `after_shuffle` walk BEFORE
    /// the next card is taken — the grid-select sees the FULL
    /// post-reshuffle pile, the draw suspends
    /// (`pending_draw_resume`), and the option list is sorted by
    /// (rarity rank, `ModelId.Entry` ordinal) per C#
    /// `StratagemPower.AfterShuffle`'s `orderby c.Rarity, c.Id` (with
    /// no rarity registry in core tests, ranks tie → entry-only).
    /// Resolving the pick adds the card to hand (a raw pile move) and
    /// resumes the suspended remainder, mirroring C#'s `await` inside
    /// `CardPileCmd.Draw`.
    #[test]
    fn stratagem_grid_selects_on_mid_draw_reshuffle_and_resumes() {
        use crate::cards::CardId;
        let (mut state, _uid) = state_with_player_power(PowerKind::Stratagem, 1);
        // Living player: the mid-draw reshuffle gate (`combat_is_ending`) skips
        // the reshuffle once combat is over/ending, and a default fixture
        // leaves the player at 0 HP (a pending loss). Give it real HP so the
        // Stratagem grid opens on the reshuffle as in a live combat.
        state.player.current_hp = 80;
        state.player.max_hp = 80;
        // Draw pile empty; discard holds three distinct cards in a
        // deliberately entry-unsorted order.
        let strike = push_test_card(&mut state, 1, CardId::StrikeIronclad);
        let bash = push_test_card(&mut state, 2, CardId::Bash);
        let defend = push_test_card(&mut state, 3, CardId::DefendIronclad);
        state.player.discard.extend([strike, bash, defend]);

        let moved = state.draw_into_hand(1);
        assert_eq!(moved, 0, "draw suspends before taking a card");
        let pc = state.pending_choice.as_ref().expect("grid-select open");
        assert_eq!(pc.kind, crate::ChoiceKind::AddFromDrawToHand);
        assert_eq!((pc.min_select, pc.max_select, pc.can_skip), (1, 1, false));
        // v0.107.1 1a.12 (`StratagemPower.cs:24` FromSimpleGrid→FromCombatPile):
        // the interactive grid STILL sorts the Draw pile by (Rarity, Id) —
        // `CardSelectCmd.FromCombatPile` re-applies `orderby c.Rarity, c.Id` for
        // a `PileType.Draw` pile in its `Selector` branch (only the auto-resolve
        // fast path stays raw). With no rarity registry in core tests every rank
        // ties at 0, so the option order is the `ModelId.Entry` (==
        // `to_python_name`) ordinal: BASH < DEFEND_IRONCLAD < STRIKE_IRONCLAD —
        // NOT the shuffle-dependent raw pile order `[bash, strike, defend]`.
        let opt_uids: Vec<crate::CardUid> = pc.options.iter().filter_map(|o| o.card_uid).collect();
        assert_eq!(
            opt_uids,
            vec![bash, defend, strike],
            "options surface sorted by (rarity, entry), not raw pile order"
        );
        let mut opt_set: Vec<CardId> = pc.options.iter().map(|o| o.card_id).collect();
        opt_set.sort_by_key(|c| c.to_python_name());
        assert_eq!(
            opt_set,
            vec![CardId::Bash, CardId::DefendIronclad, CardId::StrikeIronclad],
            "all three reshuffled draw cards are offered"
        );
        let pick = pc.options[0].card_uid.expect("option 0 has a uid");
        assert_eq!(
            state.pending_draw_resume,
            Some(crate::PendingDrawResume {
                remaining: 1,
                from_hand_draw: true,
                post_shuffle_take: true,
                ..Default::default()
            }),
            "the undrawn remainder is stashed for the post-choice resume"
        );

        // Resolve: pick option 0 (the pile-first card). The resume then draws
        // the remaining 1 card off the post-shuffle pile top.
        let mut sel: SmallVec<[u8; 4]> = SmallVec::new();
        sel.push(0);
        let _ = crate::apply(&mut state, crate::Action::ResolveChoice { selection: sel });
        assert!(state.pending_choice.is_none(), "choice consumed");
        assert!(state.pending_draw_resume.is_none(), "resume consumed");
        assert!(state.player.hand.contains(&pick), "grid pick lands in hand");
        assert_eq!(
            state.player.hand.len(),
            2,
            "pick + the resumed draw = 2 cards in hand"
        );
        assert_eq!(state.player.draw.len(), 1, "one card left in the pile");
    }

    /// Bead `sts2-rs-63mew`: C# `CardSelectCmd.FromSimpleGrid`
    /// auto-resolves when `cards.Count <= prefs.MinSelect`
    /// (`CardSelectCmd.cs:232-235`) — the entire pile is taken with NO
    /// screen. A 1-card pile under Stratagem(1) therefore moves
    /// straight to hand and the draw continues (then exhausts the empty
    /// pile and stops).
    #[test]
    fn stratagem_auto_takes_whole_pile_without_choice_when_at_or_under_amount() {
        use crate::cards::CardId;
        let (mut state, _uid) = state_with_player_power(PowerKind::Stratagem, 1);
        // Living player so the combat-ending reshuffle gate stays inert (a
        // default fixture's 0-HP player reads as a pending loss).
        state.player.current_hp = 80;
        state.player.max_hp = 80;
        let strike = push_test_card(&mut state, 1, CardId::StrikeIronclad);
        state.player.discard.push(strike);

        let moved = state.draw_into_hand(1);
        assert!(
            state.pending_choice.is_none(),
            "no screen for a covered pile"
        );
        assert!(state.pending_draw_resume.is_none());
        assert_eq!(
            moved, 0,
            "the card reached hand via the Stratagem Add (a raw pile move), not the draw"
        );
        assert_eq!(state.player.hand.len(), 1);
        assert!(state.player.hand.contains(&strike));
        assert!(state.player.draw.is_empty());
    }

    /// q6bix F-B/F-L: `SelfFormingClayPower.AfterBlockCleared`
