    /// **Poison wiring (P2-2b sts2-rs-3to):** Poison emits TWO effects on
    /// `after_side_turn_start` (when `ctx.side` matches `owner.side`):
    ///   1. `DealHpLoss` with the current `power.amount` (`UNBLOCKABLE | UNPOWERED`).
    ///   2. `DecrementPowerAmount` by -1.
    ///
    /// When `ctx.side` does NOT match `owner.side`, no effects fire.
    #[test]
    fn poison_listener_emits_dealhploss_and_decrement_on_owner_side() {
        let (state, uid) = state_with_player_power(PowerKind::Poison, 4);

        // Player-side turn start → Poison on player fires.
        let ctx = TurnSideCtx { side: Side::Player };
        let effects = collect_after_side_turn_start(&state, &ctx);
        assert_eq!(
            effects.len(),
            2,
            "Poison should emit DealHpLoss + Decrement"
        );
        match effects[0] {
            Effect::DealHpLoss {
                target,
                amount,
                props,
                ..
            } => {
                assert_eq!(target, CreatureRef::Player);
                assert_eq!(amount, 4);
                assert!(props.contains(ValueProps::UNBLOCKABLE));
                assert!(props.contains(ValueProps::UNPOWERED));
            }
            ref other => panic!("expected DealHpLoss first, got {other:?}"),
        }
        match effects[1] {
            Effect::DecrementPowerAmount { listener, delta } => {
                assert_eq!(listener, ListenerRef::Power(uid));
                assert_eq!(delta, -1);
            }
            ref other => panic!("expected DecrementPowerAmount second, got {other:?}"),
        }

        // Enemy-side turn start → Poison on player does NOT fire.
        let ctx_enemy_side = TurnSideCtx { side: Side::Enemy };
        let effects = collect_after_side_turn_start(&state, &ctx_enemy_side);
        assert!(
            effects.is_empty(),
            "Poison on player should NOT fire on enemy-side turn start"
        );
    }

