    /// **Enemy Thorns** = same `PowerKind::Thorns` mounted on an enemy.
    /// Listener guard `target is owner and dealer is not None and
    /// props.is_powered()` (damage_reactions.py:47-64). When the player
    /// powered-hits the cultist, the cultist emits a reflective
    /// `Effect::DealHpLoss` targeting the player (dealer of original
    /// hit) for `power.amount`. Reflected props carry `UNPOWERED |
    /// SKIP_HURT_ANIM` to bound recursion.
    #[test]
    fn enemy_thorns_reflects_to_player_attacker() {
        let (state, cultist) = state_with_enemy_power(PowerKind::Thorns, 3);

        // Player powered attack on cultist → Thorns fires.
        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: cultist,
            props: ValueProps::MOVE,
        };
        let effects = collect_before_damage_received(&state, &ctx);
        assert_eq!(effects.len(), 1, "Enemy Thorns should emit one DealHpLoss");
        match effects[0] {
            Effect::DealHpLoss {
                dealer,
                target,
                amount,
                props,
            } => {
                // Reflected damage flips dealer (now the cultist) /
                // target (the original attacker, the player).
                assert_eq!(
                    dealer, cultist,
                    "Enemy Thorns reflection: dealer becomes the cultist"
                );
                assert_eq!(
                    target,
                    CreatureRef::Player,
                    "Enemy Thorns reflection: target is the original attacker"
                );
                assert_eq!(amount, 3);
                assert!(
                    props.contains(ValueProps::UNPOWERED),
                    "Reflected props must carry UNPOWERED to bound recursion"
                );
                assert!(props.contains(ValueProps::SKIP_HURT_ANIM));
            }
            ref other => panic!("expected DealHpLoss, got {other:?}"),
        }

        // Unpowered attack → does NOT fire.
        let unpowered = DamageCtx {
            props: ValueProps::NONE,
            ..ctx
        };
        let effects = collect_before_damage_received(&state, &unpowered);
        assert!(
            effects.is_empty(),
            "Enemy Thorns should NOT fire on unpowered attack"
        );
    }

    /// **Enemy `FlameBarrier`** = same `PowerKind::FlameBarrier` mounted
    /// on an enemy. Listener guard mirrors Thorns but on
    /// `after_damage_received`. Reflected props carry `UNPOWERED` only
    /// (no `SKIP_HURT_ANIM` — that's Thorns-specific).
    #[test]
    fn enemy_flame_barrier_reflects_after_damage() {
        let (state, cultist) = state_with_enemy_power(PowerKind::FlameBarrier, 5);

        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: cultist,
            props: ValueProps::MOVE,
        };
        let effects = collect_after_damage_received(&state, &ctx);
        assert_eq!(
            effects.len(),
            1,
            "Enemy FlameBarrier should emit one DealHpLoss"
        );
        match effects[0] {
            Effect::DealHpLoss {
                dealer,
                target,
                amount,
                props,
            } => {
                assert_eq!(dealer, cultist);
                assert_eq!(target, CreatureRef::Player);
                assert_eq!(amount, 5);
                assert!(props.contains(ValueProps::UNPOWERED));
                assert!(
                    !props.contains(ValueProps::SKIP_HURT_ANIM),
                    "FlameBarrier (unlike Thorns) does NOT carry SKIP_HURT_ANIM"
                );
            }
            ref other => panic!("expected DealHpLoss, got {other:?}"),
        }
    }

    /// **Enemy Poison** = same `PowerKind::Poison` mounted on an enemy.
    /// Listener guard `side == owner.side and amount > 0`
    /// (turn_effects.py:491-511). Owner-side mapping: the cultist's
    /// `CreatureRef::Enemy(_)` resolves to `Side::Enemy`, so Poison on
    /// the cultist fires on `TurnSideCtx { side: Side::Enemy }` and
    /// emits a self-tick `DealHpLoss` (target = cultist) plus a
    /// `DecrementPowerAmount` by -1.
    #[test]
    fn enemy_poison_self_ticks_on_enemy_side() {
        let (state, cultist) = state_with_enemy_power(PowerKind::Poison, 4);
        let listener = ListenerRef::Power(PowerUid(NonZeroU32::new(1).unwrap()));

        // Enemy-side turn start → Poison on cultist fires.
        let enemy_side = TurnSideCtx { side: Side::Enemy };
        let effects = collect_after_side_turn_start(&state, &enemy_side);
        assert_eq!(
            effects.len(),
            2,
            "Enemy Poison should emit DealHpLoss + Decrement on enemy side"
        );
        match effects[0] {
            Effect::DealHpLoss {
                target,
                amount,
                props,
                ..
            } => {
                assert_eq!(
                    target, cultist,
                    "Enemy Poison self-ticks against the cultist"
                );
                assert_eq!(amount, 4);
                assert!(props.contains(ValueProps::UNBLOCKABLE));
                assert!(props.contains(ValueProps::UNPOWERED));
            }
            ref other => panic!("expected DealHpLoss first, got {other:?}"),
        }
        match effects[1] {
            Effect::DecrementPowerAmount { listener: l, delta } => {
                assert_eq!(l, listener);
                assert_eq!(delta, -1);
            }
            ref other => panic!("expected DecrementPowerAmount second, got {other:?}"),
        }

        // Player-side turn start → Poison on cultist does NOT fire.
        let player_side = TurnSideCtx { side: Side::Player };
        let effects = collect_after_side_turn_start(&state, &player_side);
        assert!(
            effects.is_empty(),
            "Enemy Poison should NOT fire on player-side turn start"
        );
    }

    /// **Accelerant accelerates enemy Poison** (C# `PoisonPower.TriggerCount`,
    /// PoisonPower.cs:24-33): when the player holds `AccelerantPower`, an enemy's
    /// Poison ticks `min(amount, 1 + Σ player Accelerant)` times per enemy turn,
    /// each tick dealing the decreasing amount and decrementing once. With
    /// Poison(4) + player Accelerant(1) → 2 ticks dealing 4 then 3, two
    /// decrements. Silent fuzz seeds 296/142 (RS ticked once, under-dealing).
    #[test]
    fn accelerant_makes_enemy_poison_tick_multiple_times() {
        let (mut state, _cultist) = state_with_enemy_power(PowerKind::Poison, 4);
        let pid = NonZeroU32::new(900).unwrap();
        state.powers.push(Power {
            id: pid,
            kind: PowerKind::Accelerant,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(pid));

        let enemy_side = TurnSideCtx { side: Side::Enemy };
        let effects = collect_after_side_turn_start(&state, &enemy_side);
        assert_eq!(
            effects.len(),
            4,
            "Accelerant(1) → enemy Poison ticks twice (deal+decrement each)"
        );
        let damages: SmallVec<[i32; 4]> = effects
            .iter()
            .filter_map(|e| match e {
                Effect::DealHpLoss { amount, .. } => Some(*amount),
                _ => None,
            })
            .collect();
        assert_eq!(
            damages.as_slice(),
            &[4, 3],
            "ticks deal the decreasing current amount (4 then 3)"
        );
        let decrements = effects
            .iter()
            .filter(|e| matches!(e, Effect::DecrementPowerAmount { delta: -1, .. }))
            .count();
        assert_eq!(decrements, 2, "one Decrement per trigger");
    }

    /// Accelerant's poison acceleration is capped at the poison `amount`
    /// (C# `Math.Min(Amount, 1 + …)`): Poison(1) + player Accelerant(3) still
    /// ticks only ONCE (you can't tick more times than the stack is high).
    #[test]
    fn accelerant_poison_trigger_count_capped_at_amount() {
        let (mut state, _cultist) = state_with_enemy_power(PowerKind::Poison, 1);
        let pid = NonZeroU32::new(901).unwrap();
        state.powers.push(Power {
            id: pid,
            kind: PowerKind::Accelerant,
            amount: 3,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(pid));

        let enemy_side = TurnSideCtx { side: Side::Enemy };
        let effects = collect_after_side_turn_start(&state, &enemy_side);
        assert_eq!(
            effects.len(),
            2,
            "Poison(1) caps TriggerCount at 1 regardless of Accelerant(3)"
        );
    }

    /// **Strength on enemy A does not buff enemy B's attacks** — proves
    /// `owner_of_listener` correctly distinguishes between two enemy
    /// owners. Sets up two cultists, mounts Strength(5) on cultist A,
    /// fires a powered attack from cultist B → no additive bonus.
    /// This is the multi-enemy correctness invariant the v7d guards
    /// were designed to enforce.
    #[test]
    fn enemy_strength_does_not_cross_owner_boundary() {
        let mut state = CombatState::default();

        // Cultist A holds Strength(5).
        let str_pid = NonZeroU32::new(1).unwrap();
        state.powers.push(Power {
            id: str_pid,
            kind: PowerKind::Strength,
            amount: 5,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        let mut a_powers: SmallVec<[PowerUid; 8]> = SmallVec::new();
        a_powers.push(PowerUid(str_pid));
        state.creatures.push(Creature {
            id: NonZeroU32::new(1).unwrap(),
            current_hp: 48,
            max_hp: 48,
            block: 0,
            powers: a_powers,
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(1).unwrap());

        // Cultist B has no powers.
        state.creatures.push(Creature {
            id: NonZeroU32::new(2).unwrap(),
            current_hp: 48,
            max_hp: 48,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(2).unwrap());

        let cultist_a = CreatureRef::Enemy(CreatureUid::new(1).unwrap());
        let cultist_b = CreatureRef::Enemy(CreatureUid::new(2).unwrap());

        // Cultist A attacks → +5 (owner == dealer).
        let a_attacks = DamageCtx {
            dealer: cultist_a,
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        assert_eq!(
            dispatch_modify_damage_additive(&state, &a_attacks),
            5,
            "Strength on cultist A should fire when A attacks"
        );

        // Cultist B attacks → 0 (dealer != owner of A's Strength).
        let b_attacks = DamageCtx {
            dealer: cultist_b,
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        assert_eq!(
            dispatch_modify_damage_additive(&state, &b_attacks),
            0,
            "Strength on cultist A should NOT buff cultist B's attacks"
        );
    }

    /// **Player power on enemy creature does not fire for player-owned
    /// guards (and vice versa)** — the boundary test the bead spec
    /// asks for. Mounts Strength on the cultist; verifies a player
    /// attack (player as dealer) does NOT pick up the bonus through
    /// the additive dispatcher (because the cultist's Strength has
    /// `dealer != owner`).
    ///
    /// Equivalently: this proves that the same `PowerKind::Strength`
    /// variant routes correctly based on the owning creature, which is
    /// the entire premise of Option B.
    #[test]
    fn player_attack_does_not_consume_enemy_strength() {
        let (state, cultist) = state_with_enemy_power(PowerKind::Strength, 7);

        // Player attacks the cultist → Strength on cultist does NOT
        // fire (dealer = Player, owner = Enemy).
        let player_attacks = DamageCtx {
            dealer: CreatureRef::Player,
            target: cultist,
            props: ValueProps::MOVE,
        };
        assert_eq!(
            dispatch_modify_damage_additive(&state, &player_attacks),
            0,
            "Enemy Strength must NOT buff player's attacks"
        );
        assert_eq!(
            modify_damage(&state, 6, &player_attacks),
            6,
            "Pipeline must pass raw damage through unchanged"
        );

        // Symmetric check: place a player Vulnerable, attack from
        // an enemy targeting another enemy. Vulnerable on player
        // should NOT fire when neither dealer nor target is the
        // player.
        let mut state = state;
        let vuln_pid = NonZeroU32::new(99).unwrap();
        state.powers.push(Power {
            id: vuln_pid,
            kind: PowerKind::Vulnerable,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(PowerUid(vuln_pid));

        let enemy_to_enemy = DamageCtx {
            dealer: cultist,
            target: cultist, // self-targeting (synthetic) — owner check still applies
            props: ValueProps::MOVE,
        };
        // Vulnerable on player has owner = Player; target = cultist
        // ≠ Player → guard fails → ONE.
        assert_eq!(
            dispatch_modify_damage_multiplicative(&state, &enemy_to_enemy),
            DamageMul::ONE,
            "Player Vulnerable must NOT fire when player is neither dealer nor target"
        );
    }

    // -----------------------------------------------------------------
    // P3-6 sts2-rs-p1n: Vulnerable / Weak / Frail tick down on
    // `on_turn_end_enemy_side`, fired by `dispatch_after_turn_end` only
    // when `ctx.side == Side::Enemy`. Mirrors Python's
    // `fire_after_turn_end` synthetic guard at hooks.py:391-403.
    // -----------------------------------------------------------------

    /// Vulnerable's `on_turn_end_enemy_side` arm emits exactly one
    /// `Effect::DecrementPowerAmount` with `delta = -1` targeting the
    /// listener's own `PowerUid`. Locks the per-listener body against
    /// Python `common.py:75-79`.
    #[test]
    fn vulnerable_emits_decrement_on_turn_end_enemy_side() {
        let (state, uid) = state_with_player_power(PowerKind::Vulnerable, 2);
        let effects = collect_on_turn_end_enemy_side(&state, &TurnSelfCtx::default());
        assert_eq!(effects.len(), 1, "Vulnerable should emit one tick");
        match effects[0] {
            Effect::TickPowerOrSkip { listener, delta } => {
                assert_eq!(listener, ListenerRef::Power(uid));
                assert_eq!(delta, -1);
            }
            ref other => panic!("expected TickPowerOrSkip, got {other:?}"),
        }
    }

    /// Weak and Frail's `on_turn_end_enemy_side` arms each emit a single
    /// `DecrementPowerAmount(-1)`. Combined with Vulnerable, three powers
    /// produce three effects in iteration order.
    #[test]
    fn weak_frail_emit_decrement_on_turn_end_enemy_side() {
        for kind in [PowerKind::Weak, PowerKind::Frail] {
            let (state, uid) = state_with_player_power(kind, 1);
            let effects = collect_on_turn_end_enemy_side(&state, &TurnSelfCtx::default());
            assert_eq!(effects.len(), 1, "{kind:?} should emit one tick");
            match effects[0] {
                Effect::TickPowerOrSkip { listener, delta } => {
                    assert_eq!(listener, ListenerRef::Power(uid));
                    assert_eq!(delta, -1);
                }
                ref other => panic!("expected TickPowerOrSkip, got {other:?}"),
            }
        }
    }

    /// Powers OTHER than Vulnerable/Weak/Frail do NOT emit any effect
    /// from `on_turn_end_enemy_side`. Locks the negative case against
    /// Python's per-power method-table introspection (Strength /
    /// Dexterity / Intangible / Artifact / Thorns / `FlameBarrier` /
    /// Poison all leave the `PowerInstance.on_turn_end_enemy_side`
    /// default → no fire).
    #[test]
    fn non_duration_debuffs_do_not_tick_on_turn_end_enemy_side() {
        let kinds = [
            PowerKind::Strength,
            PowerKind::Dexterity,
            PowerKind::Intangible,
            PowerKind::Artifact,
            PowerKind::Thorns,
            PowerKind::FlameBarrier,
            PowerKind::Poison,
        ];
        for k in kinds {
            let (state, _) = state_with_player_power(k, 5);
            let effects = collect_on_turn_end_enemy_side(&state, &TurnSelfCtx::default());
            assert!(
                effects.is_empty(),
                "{k:?} should NOT emit on on_turn_end_enemy_side",
            );
        }
    }

    /// `dispatch_after_turn_end` with `ctx.side == Side::Enemy` walks
    /// the synthetic guard and applies the decrement effects. With
    /// Vulnerable(3) attached, post-dispatch the power's `amount` is 2.
    #[test]
    fn dispatch_after_turn_end_enemy_side_ticks_vulnerable() {
        let (mut state, uid) = state_with_player_power(PowerKind::Vulnerable, 3);
        let ctx = TurnSideCtx { side: Side::Enemy };

        dispatch_after_turn_end(&mut state, &ctx);

        let power = state
            .powers
            .iter()
            .find(|p| p.id == uid.0)
            .expect("Vulnerable instance still attached");
        assert_eq!(
            power.amount, 2,
            "dispatch_after_turn_end(Enemy) should tick Vulnerable(3) -> Vulnerable(2)",
        );
    }

    /// Bead `sts2-rs-st9tl`: a Vulnerable freshly applied to a MONSTER
    /// (e.g. by a player card) must decrement at the very next
    /// enemy-turn-end — it does NOT arm `skip_next_tick` (that's
    /// player-target-only per C# `PowerCmd.cs:104`). End-to-end repro
    /// of the monster-Vulnerable-stuck-one-tick-high parity drift
    /// (Rust 2 vs C# 1).
    #[test]
    fn dispatch_after_turn_end_enemy_side_decrements_fresh_monster_vulnerable() {
        let mut state = CombatState::default();
        let monster_uid = state.spawn_enemy(crate::MonsterKind::Nibbit);
        crate::card_effects::apply_power_to_creature(
            &mut state,
            monster_uid,
            PowerKind::Vulnerable,
            2,
        );
        // Sanity: fresh monster Vulnerable did not arm the skip flag.
        let vuln = state
            .powers
            .iter()
            .find(|p| p.kind == PowerKind::Vulnerable)
            .expect("Vulnerable on monster");
        assert!(!vuln.skip_next_tick, "monster Vulnerable must not skip");

        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });

        let vuln = state
            .powers
            .iter()
            .find(|p| p.kind == PowerKind::Vulnerable)
            .expect("Vulnerable still attached");
        assert_eq!(
            vuln.amount, 1,
            "fresh monster Vulnerable(2) should tick to 1 at enemy-turn-end (was stuck at 2)",
        );
    }

    /// Bead `sts2-rs-o1mwv` (C.4 follow-up): a V/W/F debuff whose duration
    /// ticks to 0 at enemy-turn-end is REMOVED from the creature (C#
    /// `PowerModel.ShouldRemoveDueToAmount` at `Amount <= 0`), not left
    /// lingering at amount 0. Regression for the SHRINKER_BEETLE_WEAK
    /// parity divergence (`monsters[0].powers.len` C#=0 Rust=1).
    #[test]
    fn dispatch_after_turn_end_enemy_side_removes_vulnerable_when_it_ticks_to_zero() {
        let mut state = CombatState::default();
        let monster_uid = state.spawn_enemy(crate::MonsterKind::Nibbit);
        // Vulnerable(1): a non-fresh tick (skip flag already consumed) so
        // the next enemy-turn-end tick takes it 1 -> 0.
        crate::card_effects::apply_power_to_creature(
            &mut state,
            monster_uid,
            PowerKind::Vulnerable,
            1,
        );
        // Clear any skip flag so the tick actually decrements this turn.
        for p in &mut state.powers {
            if p.kind == PowerKind::Vulnerable {
                p.skip_next_tick = false;
            }
        }

        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });

        assert!(
            !state.powers.iter().any(|p| p.kind == PowerKind::Vulnerable),
            "Vulnerable ticking 1 -> 0 must be removed from the power arena"
        );
        let monster = state
            .creatures
            .iter()
            .find(|c| c.id == monster_uid.0)
            .expect("monster present");
        assert!(
            monster.powers.is_empty(),
            "the 0-amount Vulnerable must be removed from the creature's power list"
        );
    }

    /// `NemesisPower.AfterSideTurnEnd` (NemesisPower.cs:20-35): the TestSubject's
    /// 3rd-form Nemesis toggles `IntangiblePower(1)` on the owner every other
    /// enemy-turn-end. Verify the alternating cadence: apply → (removed) → apply.
    /// Combined with `IntangiblePower.AfterTurnEnd` (which removes at the next
    /// enemy-turn-end), this makes the boss Intangible on every other player turn.
    #[test]
    fn nemesis_toggles_intangible_every_other_enemy_turn_end() {
        let mut state = CombatState::default();
        let monster_uid = state.spawn_enemy(crate::MonsterKind::Nibbit);
        crate::card_effects::apply_power_to_creature(
            &mut state,
            monster_uid,
            PowerKind::Nemesis,
            1,
        );
        let has_intangible = |s: &CombatState| {
            s.creatures
                .iter()
                .find(|c| c.id == monster_uid.0)
                .is_some_and(|c| {
                    c.powers.iter().any(|pu| {
                        s.powers
                            .get_by_id(pu.0)
                            .is_some_and(|p| p.kind == PowerKind::Intangible)
                    })
                })
        };
        assert!(!has_intangible(&state), "no Intangible before any turn end");

        // 1st enemy-turn-end: toggle ON → Intangible(1) applied.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert!(
            has_intangible(&state),
            "1st enemy-turn-end: Nemesis applies Intangible(1)"
        );

        // 2nd enemy-turn-end: Intangible arm removes it; Nemesis declines to
        // re-apply (owner still Intangible in the snapshot).
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert!(
            !has_intangible(&state),
            "2nd enemy-turn-end: Intangible removed, not re-applied (toggle OFF)"
        );

        // 3rd enemy-turn-end: toggle ON again.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert!(
            has_intangible(&state),
            "3rd enemy-turn-end: Nemesis re-applies Intangible(1)"
        );
    }

    /// C# `NemesisPower.AfterSideTurnEnd` removes the owner's Intangible inside
    /// its own listener (NemesisPower.cs:30-33), so a Demise applied after
    /// Nemesis ticks on a tangible owner in the same walk. Rust left the
    /// removal to Intangible's tick-down, which runs after the Demise when the
    /// Intangible was (re)applied later, so the Demise tick was capped at 1 (Defect 5980 v0.107.1 @680:
    /// monsters[0].hp cs=207 rs=215).
    #[test]
    fn nemesis_removes_intangible_before_a_later_demise_tick() {
        let mut state = CombatState::default();
        let monster_uid = state.spawn_enemy(crate::MonsterKind::Nibbit);
        crate::card_effects::apply_power_to_creature(
            &mut state,
            monster_uid,
            PowerKind::Nemesis,
            1,
        );
        crate::card_effects::apply_power_to_creature(&mut state, monster_uid, PowerKind::Demise, 9);
        // Toggle ON: Intangible(1), listed after the Demise.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        let hp = |s: &CombatState| {
            s.creatures
                .iter()
                .find(|c| c.id == monster_uid.0)
                .expect("monster")
                .current_hp
        };
        let before = hp(&state);
        // Toggle OFF, then Demise.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert_eq!(before - hp(&state), 9, "Demise hits a tangible owner");
        assert!(
            !state.powers.iter().any(|p| p.kind == PowerKind::Intangible),
            "Intangible removed"
        );
    }

    /// A player-side turn end must NOT toggle Nemesis (owner is an enemy that
    /// only participates in enemy turns — C# `participants.Contains(Owner)`).
    #[test]
    fn nemesis_does_not_toggle_on_player_side_turn_end() {
        let mut state = CombatState::default();
        let monster_uid = state.spawn_enemy(crate::MonsterKind::Nibbit);
        crate::card_effects::apply_power_to_creature(
            &mut state,
            monster_uid,
            PowerKind::Nemesis,
            1,
        );
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        let has_intangible = state
            .creatures
            .iter()
            .find(|c| c.id == monster_uid.0)
            .is_some_and(|c| {
                c.powers.iter().any(|pu| {
                    state
                        .powers
                        .get_by_id(pu.0)
                        .is_some_and(|p| p.kind == PowerKind::Intangible)
                })
            });
        assert!(
            !has_intangible,
            "player-side turn end must not apply Intangible via Nemesis"
        );
    }

