    /// Constrict(6) under Intangible(1) with 3 Block, ticked at the player's
    /// turn end. Returns `(hp, block)`.
    fn constrict_tick_under_intangible(version: crate::GameVersion) -> (i32, i32) {
        let (mut state, _) = state_with_player_power(PowerKind::Constrict, 6);
        state.game_version = version;
        let intangible = power_uid(2);
        state.powers.push(Power {
            id: intangible.0,
            kind: PowerKind::Intangible,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(intangible);
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        state.player.block = 3;
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        (state.player.current_hp, state.player.block)
    }

    /// A lethal 1-damage Unblockable self-tick on a 1-HP player holding
    /// Inferno(6), on the player's side. Returns the enemy's HP loss.
    fn inferno_fan_on_lethal_self_tick(version: crate::GameVersion) -> i32 {
        let mut state = CombatState {
            game_version: version,
            ..Default::default()
        };
        state.side = Side::Player;
        state.player.current_hp = 1;
        state.player.max_hp = 60;
        let player = state.init_player_creature();
        crate::card_effects::apply_power_to_creature(&mut state, player, PowerKind::Inferno, 6);
        let enemy = state.spawn_enemy(crate::MonsterKind::Nibbit);
        let hp_of = |s: &CombatState| {
            s.creatures
                .iter()
                .find(|c| c.id == enemy.0)
                .map_or(0, |c| c.current_hp)
        };
        let before = hp_of(&state);
        apply_effect(
            &mut state,
            Effect::DealHpLoss {
                dealer: CreatureRef::Player,
                target: CreatureRef::Player,
                amount: 1,
                props: ValueProps::UNBLOCKABLE.union(ValueProps::UNPOWERED),
            },
        );
        assert_eq!(state.player.current_hp, 0, "the tick is lethal");
        before - hp_of(&state)
    }

    /// `CreatureCmd.Damage` skips `AfterDamageReceived` for a killed target
    /// (v0.111.0 CreatureCmd.cs:414, v0.107.1 :392), so Inferno does not fan.
    /// Same C# in both builds (GH #806).
    #[test]
    fn inferno_skips_lethal_self_tick_both_versions() {
        for version in [crate::GameVersion::V0_107_1, crate::GameVersion::V0_111_0] {
            assert_eq!(inferno_fan_on_lethal_self_tick(version), 0, "{version:?}");
        }
    }

    /// `CreatureCmd.Damage` caps the tick at 1 before Block (`Hook.ModifyDamage`
    /// Cap step, v0.111.0 CreatureCmd.cs:283, v0.107.1 :261), so 1 Block is
    /// spent and no HP is lost (the Silent `card+:WRAITH_FORM` sweep subject).
    /// Same C# in both builds (GH #806).
    #[test]
    fn constrict_under_intangible_is_capped_before_block_both_versions() {
        for version in [crate::GameVersion::V0_107_1, crate::GameVersion::V0_111_0] {
            assert_eq!(
                constrict_tick_under_intangible(version),
                (50, 2),
                "{version:?}"
            );
        }
    }

    /// Bead `sts2-rs-2e9q2`: when Constrict's end-of-turn self-damage zeroes
    /// the player, the player dies and C# clears its powers
    /// (`RemoveAllPowersAfterDeath`). This is the exact coverage-sweep path —
    /// the self-damage flows through `apply_dealhploss`'s player branch, which
    /// flips `is_over`/`player_won` AND must now clear the lingering Constrict,
    /// matching C#'s post-defeat `player.powers == []`.
    #[test]
    fn after_turn_end_lethal_constrict_clears_player_powers_on_death() {
        let (mut state, _uid) = state_with_player_power(PowerKind::Constrict, 9);
        state.player.current_hp = 7;
        state.player.max_hp = 80;
        state.player.block = 0;

        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });

        assert_eq!(
            state.player.current_hp, 0,
            "Constrict(9) kills the 7-HP player"
        );
        assert!(state.is_over && !state.player_won, "player defeat flagged");
        assert!(
            state.player.powers.is_empty(),
            "C# RemoveAllPowersAfterDeath: player powers cleared on death"
        );
        assert!(
            state.powers.iter().all(|p| p.kind != PowerKind::Constrict),
            "central Constrict row unlinked on death"
        );
    }

