    // ---- Necrobinder NecroMastery (after_current_hp_changed reflect) ----

    /// Build (state, enemy_uid, osty_uid) with one 40/40 enemy, a living Osty,
    /// and `NecroMastery(amount)` on the player. The summon mints a DieForYou
    /// power at id 1, so the NecroMastery power uses id 99 to avoid a collision.
    fn state_with_necro_mastery(amount: i32) -> (CombatState, CreatureUid, CreatureUid) {
        let mut state = CombatState::default();
        state.creatures.push(Creature {
            id: NonZeroU32::new(1).unwrap(),
            current_hp: 40,
            max_hp: 40,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        let enemy_uid = CreatureUid::new(1).unwrap();
        state.enemy_uids.push(enemy_uid);
        let osty_uid = state.summon_osty(10).expect("summon osty");
        let pid = power_uid(99);
        state.powers.push(Power {
            id: pid.0,
            kind: PowerKind::NecroMastery,
            amount,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(pid);
        (state, enemy_uid, osty_uid)
    }

    /// C# hands `NecroMasteryPower.AfterCurrentHpChanged` the HP the Osty
    /// actually lost (`DamageResult.UnblockedDamage = currentHp - CurrentHp`,
    /// Creature.cs:446-457), not the overkill: Thorns 5 into a 2-HP Osty
    /// reflects 2 (act23 Necrobinder:1008, Rust reflected 5).
    #[test]
    fn necro_mastery_reflects_only_the_hp_an_overkilled_osty_had() {
        let (mut state, enemy_uid, osty_uid) = state_with_necro_mastery(1);
        state.player.current_hp = 50;
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == osty_uid.0) {
            c.current_hp = 2;
        }
        let _ = crate::damage::apply_damage(
            &mut state,
            CreatureRef::Enemy(enemy_uid),
            osty_uid,
            5,
            ValueProps::UNPOWERED,
            None,
        );
        let enemy = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .unwrap();
        assert_eq!(enemy.current_hp, 38, "reflects the 2 HP lost, not 5");
    }

    /// C# `NecroMasteryPower.AfterCurrentHpChanged`: when the player's Osty
    /// loses HP, deal `lostHp * Amount` UNBLOCKABLE | UNPOWERED damage to all
    /// hittable enemies. Osty loses 4, NecroMastery(2) → the enemy loses 8 HP,
    /// bypassing its block (unblockable).
    #[test]
    fn necro_mastery_osty_hp_loss_reflects_to_all_enemies() {
        let (mut state, enemy_uid, osty_uid) = state_with_necro_mastery(2);
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy_uid.0) {
            c.block = 5;
        }
        dispatch_after_current_hp_changed(&mut state, osty_uid, -4);
        let enemy = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .unwrap();
        assert_eq!(
            enemy.current_hp, 32,
            "enemy loses lostHp(4) * Amount(2) = 8"
        );
        assert_eq!(enemy.block, 5, "reflect is unblockable — block untouched");
    }

    /// A POSITIVE delta (heal) on the Osty is a no-op — C# gates on
    /// `!(delta >= 0)`.
    #[test]
    fn necro_mastery_osty_heal_does_not_reflect() {
        let (mut state, enemy_uid, osty_uid) = state_with_necro_mastery(2);
        dispatch_after_current_hp_changed(&mut state, osty_uid, 4);
        let enemy = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .unwrap();
        assert_eq!(enemy.current_hp, 40, "a heal must not reflect damage");
    }

    /// HP loss on a creature that is NOT the player's Osty does not reflect —
    /// C# gates on `creature.Monster is Osty && creature.PetOwner == Owner`.
    #[test]
    fn necro_mastery_non_osty_hp_loss_does_not_reflect() {
        let (mut state, enemy_uid, _osty_uid) = state_with_necro_mastery(2);
        // Pass the enemy's own uid as the changed creature — not the pet.
        dispatch_after_current_hp_changed(&mut state, enemy_uid, -4);
        let enemy = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .unwrap();
        assert_eq!(
            enemy.current_hp, 40,
            "only the player's Osty losing HP triggers NecroMastery"
        );
    }

    /// With no NecroMastery active, an Osty HP-loss is inert.
    #[test]
    fn necro_mastery_absent_no_reflect() {
        let (mut state, enemy_uid, osty_uid) = state_with_necro_mastery(2);
        // Remove the NecroMastery power.
        state.powers.retain(|p| p.kind != PowerKind::NecroMastery);
        state.player.powers.clear();
        dispatch_after_current_hp_changed(&mut state, osty_uid, -4);
        let enemy = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .unwrap();
        assert_eq!(enemy.current_hp, 40, "no NecroMastery → no reflect");
    }

