    /// C# `DebilitatePower.ModifyVulnerableMultiplier`: a Vulnerable+Debilitate
    /// target takes a powered hit at ×2.0 (vs ×1.5 from Vulnerable alone).
    #[test]
    fn debilitate_doubles_vulnerable_excess() {
        let (mut state, enemy_uid) = state_with_one_enemy();
        let v = power_uid(1);
        let d = power_uid(2);
        state.powers.push(Power {
            id: v.0,
            kind: PowerKind::Vulnerable,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.powers.push(Power {
            id: d.0,
            kind: PowerKind::Debilitate,
            amount: 3,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy_uid.0) {
            c.powers.push(v);
            c.powers.push(d);
        }
        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: CreatureRef::Enemy(enemy_uid),
            props: ValueProps::MOVE,
        };
        // Vulnerable alone: floor(10 * 1.5) = 15. With Debilitate: floor(10 * 2.0) = 20.
        assert_eq!(modify_damage(&state, 10, &ctx), 20);
    }

    /// C# `DebilitatePower.ModifyWeakMultiplier`: a Weak+Debilitate dealer's
    /// powered attack lands at ×0.5 (vs ×0.75 from Weak alone).
    #[test]
    fn debilitate_deepens_weak() {
        let (mut state, enemy_uid) = state_with_one_enemy();
        let w = power_uid(1);
        let d = power_uid(2);
        state.powers.push(Power {
            id: w.0,
            kind: PowerKind::Weak,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.powers.push(Power {
            id: d.0,
            kind: PowerKind::Debilitate,
            amount: 3,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy_uid.0) {
            c.powers.push(w);
            c.powers.push(d);
        }
        // Enemy (Weak'd dealer) attacks the player with a powered hit.
        let ctx = DamageCtx {
            dealer: CreatureRef::Enemy(enemy_uid),
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        // Weak alone: floor(10 * 0.75) = 7. With Debilitate: floor(10 * 0.5) = 5.
        assert_eq!(modify_damage(&state, 10, &ctx), 5);
    }

    /// `DebilitatePower.AfterTurnEnd`: decrements on the owner's (enemy's) turn
    /// end and is removed at 0.
    #[test]
    fn debilitate_decrements_at_enemy_turn_end() {
        let (state, _enemy) = state_with_enemy_power(PowerKind::Debilitate, 2);
        let mut state = state;
        let pid = NonZeroU32::new(1).unwrap();

        // Player turn end: no change (owner side is Enemy).
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(state.powers.get_by_id(pid).map(|p| p.amount), Some(2));
        // Enemy turn end: 2 → 1.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert_eq!(state.powers.get_by_id(pid).map(|p| p.amount), Some(1));
        // Again: 1 → 0, removed.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert!(
            !state.powers.iter().any(|p| p.id == pid),
            "Debilitate removed at 0 stacks"
        );
    }

    /// C# `DanseMacabrePower.BeforeCardPlayed`: gain `Amount` block when the
    /// owner plays a card whose resolved cost >= 2 (the EnergyVar threshold);
    /// nothing on a cheaper card.
    #[test]
    fn danse_macabre_grants_block_on_cost_two_or_more() {
        let (mut state, _pid) = state_with_player_power(PowerKind::DanseMacabre, 4);

        // Resolved cost 1 (< 2): no block.
        dispatch_before_card_played_powers(&mut state, 1, false);
        assert_eq!(
            state.player.block, 0,
            "cost 1 is below the EnergyVar threshold"
        );

        // Resolved cost 2 (>= 2): gain 4 block.
        dispatch_before_card_played_powers(&mut state, 2, false);
        assert_eq!(
            state.player.block, 4,
            "cost 2 meets the threshold → +4 block"
        );

        // Resolved cost 3 (>= 2): gain another 4 (fires per qualifying play).
        dispatch_before_card_played_powers(&mut state, 3, false);
        assert_eq!(state.player.block, 8);
    }

