    /// NoBlock (PanicButton) — C# decrements only on the enemy turn end;
    /// survives the player turn end unchanged.
    #[test]
    fn after_turn_end_no_block_decrements_on_enemy_side_only() {
        let (mut state, uid) = state_with_player_power(PowerKind::NoBlock, 2);
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0)
                .map(|p| p.amount),
            Some(2),
            "NoBlock unchanged at player turn end"
        );
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert_eq!(
            state
                .powers
                .iter()
                .find(|p| p.id == uid.0)
                .map(|p| p.amount),
            Some(1),
            "NoBlock decrements at enemy turn end"
        );
    }

