    /// Bead `sts2-rs-gl5f6`: `DuplicationPower.AfterModifyingCardPlayCount`
    /// (C# DuplicationPower.cs:25-28) decrements the power after each
    /// boosted card play, and removes it once it reaches 0.
    #[test]
    fn duplication_after_modifying_card_play_count_decrements_and_removes_at_zero() {
        // amount=1 → remove on first trigger.
        let (mut state, uid) = state_with_player_power(PowerKind::Duplication, 1);
        let listener = ListenerRef::Power(uid);
        let ctx = CardCtx::default();
        let effects =
            after_modifying_card_play_count(&state, listener, &ctx).expect("should emit effects");
        assert!(
            effects
                .iter()
                .any(|e| matches!(e, Effect::RemovePower { .. })),
            "amount=1 should emit RemovePower"
        );
        // Apply effects and verify removal.
        apply_effects(&mut state, &effects);
        assert!(
            !state.powers.iter().any(|p| p.id == uid.0),
            "power removed after decrement at amount=1"
        );

        // amount=2 → only decrement.
        let (state2, uid2) = state_with_player_power(PowerKind::Duplication, 2);
        let listener2 = ListenerRef::Power(uid2);
        let effects2 = after_modifying_card_play_count(&state2, listener2, &ctx)
            .expect("should emit effects for amount=2");
        assert!(
            effects2
                .iter()
                .any(|e| matches!(e, Effect::DecrementPowerAmount { delta: -1, .. })),
            "amount=2 should emit DecrementPowerAmount(-1)"
        );
        assert!(
            !effects2
                .iter()
                .any(|e| matches!(e, Effect::RemovePower { .. })),
            "amount=2 must not emit RemovePower"
        );
    }

