    /// Bead `sts2-rs-j0ek`: Vulnerable with `skip_next_tick = true`
    /// consumes the flag on the first enemy-side tick instead of
    /// decrementing. Mirrors Python's `power_listener.skip_next_tick`
    /// short-circuit at `common.py:75-79`.
    #[test]
    fn skip_next_tick_consumes_flag_on_first_tick_without_decrement() {
        let (mut state, uid) = state_with_player_power(PowerKind::Vulnerable, 3);
        if let Some(p) = state.powers.get_mut_by_id(uid.0) {
            p.skip_next_tick = true;
        }
        let ctx = TurnSideCtx { side: Side::Enemy };

        dispatch_after_turn_end(&mut state, &ctx);

        let power = state
            .powers
            .iter()
            .find(|p| p.id == uid.0)
            .expect("Vulnerable still attached");
        assert_eq!(
            power.amount, 3,
            "first tick with skip_next_tick=true must NOT decrement",
        );
        assert!(
            !power.skip_next_tick,
            "first tick must consume the skip flag",
        );

        // Second tick: flag is cleared, normal decrement applies.
        dispatch_after_turn_end(&mut state, &ctx);
        let power = state
            .powers
            .iter()
            .find(|p| p.id == uid.0)
            .expect("Vulnerable still attached");
        assert_eq!(
            power.amount, 2,
            "second tick should decrement normally after flag consumed",
        );
    }

    /// Bead `sts2-rs-j0ek`: the skip-flag semantics apply to Weak and
    /// Frail identically.
    #[test]
    fn skip_next_tick_applies_to_weak_and_frail() {
        for kind in [PowerKind::Weak, PowerKind::Frail] {
            let (mut state, uid) = state_with_player_power(kind, 2);
            if let Some(p) = state.powers.get_mut_by_id(uid.0) {
                p.skip_next_tick = true;
            }
            let ctx = TurnSideCtx { side: Side::Enemy };
            dispatch_after_turn_end(&mut state, &ctx);
            let power = state.powers.get_by_id(uid.0).unwrap();
            assert_eq!(power.amount, 2, "{kind:?}: first tick must not decrement");
            assert!(!power.skip_next_tick, "{kind:?}: flag must be consumed");
        }
    }

    /// `dispatch_after_turn_end` with `ctx.side == Side::Player` does
    /// NOT fire the synthetic guard — Python's hooks.py:396 guards
    /// `if side == CombatSide.ENEMY`. With Vulnerable(3) attached and
    /// player-side fired, the amount stays at 3.
    #[test]
    fn dispatch_after_turn_end_player_side_does_not_tick() {
        let (mut state, uid) = state_with_player_power(PowerKind::Vulnerable, 3);
        let ctx = TurnSideCtx { side: Side::Player };

        dispatch_after_turn_end(&mut state, &ctx);

        let power = state
            .powers
            .iter()
            .find(|p| p.id == uid.0)
            .expect("Vulnerable instance still attached");
        assert_eq!(
            power.amount, 3,
            "dispatch_after_turn_end(Player) must NOT tick — synthetic guard gates on Side::Enemy",
        );
    }

    /// An infinite Shrink (amount < 0, the monster-applied form) must NOT
    /// tick down on the owner's turn end. C# `ShrinkPower.AfterTurnEnd`
    /// gates on `!IsInfinite` (IsInfinite ⟺ amount < 0); a monster's
    /// Shrink(-1) persists at -1 every turn. The Rust arm previously
    /// decremented unconditionally, corrupting -1 → -2 → -3. q6bix.
    #[test]
    fn shrink_infinite_does_not_tick_on_player_turn_end() {
        let (mut state, uid) = state_with_player_power(PowerKind::Shrink, -1);
        let ctx = TurnSideCtx { side: Side::Player };

        dispatch_after_turn_end(&mut state, &ctx);

        let power = state
            .powers
            .iter()
            .find(|p| p.id == uid.0)
            .expect("infinite Shrink still attached");
        assert_eq!(
            power.amount, -1,
            "infinite Shrink (amount < 0) must not tick down (C# !IsInfinite gate)",
        );
    }

    /// Decrement applied to a power at `amount = 1` produces `amount = 0`
    /// (no underflow, no instance removal). Mirrors Python's stale-
    /// instance retention semantics — `on_turn_end_enemy_side` does NOT
    /// call `del owner.powers[power_id]`. The parity exporter filters
    /// `amount == 0` at serialization, so byte-equality with Python is
    /// preserved without a removal step.
    #[test]
    fn decrement_to_zero_removes_power_instance() {
        // Bead `sts2-rs-o1mwv` (C.4 follow-up): a V/W/F debuff ticking to
        // 0 is removed (C# `ShouldRemoveDueToAmount`), superseding the
        // old "keep Vulnerable(0) to match Python" contract.
        let (mut state, uid) = state_with_player_power(PowerKind::Vulnerable, 1);
        let ctx = TurnSideCtx { side: Side::Enemy };

        dispatch_after_turn_end(&mut state, &ctx);

        assert!(
            !state.powers.iter().any(|p| p.id == uid.0),
            "Vulnerable(1) ticking to 0 must be removed from the arena",
        );
        assert!(
            !state.player.powers.iter().any(|u| u.0 == uid.0),
            "the removed Vulnerable must also leave the player's power list",
        );
    }

    /// Issue #30 clamp: a power at `amount = 0` does not drift negative
    /// after repeated ticks — `TickPowerOrSkip` / `DecrementPowerAmount`
    /// clamp the post-tick amount at 0.
    #[test]
    fn decrement_does_not_underflow_below_i32_min() {
        // Vulnerable(0) is removed on its first tick (bead sts2-rs-o1mwv
        // C.4 follow-up); the clamp/removal means repeated ticks can't
        // underflow i32::MIN — there is no longer a power instance to
        // tick after the first pass.
        let (mut state, uid) = state_with_player_power(PowerKind::Vulnerable, 0);
        let ctx = TurnSideCtx { side: Side::Enemy };

        for _ in 0..3 {
            dispatch_after_turn_end(&mut state, &ctx);
        }

        assert!(
            !state.powers.iter().any(|p| p.id == uid.0),
            "Vulnerable(0) is removed on tick; repeated ticks stay safe (no underflow/panic)",
        );
    }

    // -------------------------------------------------------------------
    // Bead `sts2-rs-zlx.1`: on-card-exhaust listener bus tests.
    //
    //   - FeelNoPainPower.after_card_exhausted (lines 137-140)
    //   - DarkEmbracePower.after_card_exhausted (lines 114-117)
    // -------------------------------------------------------------------

    /// **FNP arm**: FeelNoPain(3) on the player + a single exhaust →
    /// +3 block on the player (routed through `gain_block_player` so
    /// the `modify_block` chain folds in; no Frail/Dex present in this
    /// fixture, so the additive identity is `+3`).
    ///
    /// Pin: `card_play_effects.py:137-140` — `owner.gain_block(self.amount)`.
    #[test]
    fn feel_no_pain_grants_block_on_exhaust() {
        let (mut state, _uid) = state_with_player_power(PowerKind::FeelNoPain, 3);
        let starting_block = state.player.block;
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);
        assert_eq!(
            state.player.block - starting_block,
            3,
            "FeelNoPain(3) must grant +3 block per exhaust",
        );
    }

    /// **DE arm**: DarkEmbrace(1) on the player + a single exhaust →
    /// +1 card drawn from `state.player.draw` into `state.player.hand`.
    ///
    /// Pin: `card_play_effects.py:114-117` — `combat._draw_cards(self.amount)`.
    #[test]
    fn dark_embrace_draws_on_exhaust() {
        use crate::cards::{CardId, CardType, TargetType};
        let (mut state, _uid) = state_with_player_power(PowerKind::DarkEmbrace, 1);
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;

        // Seed one card in the draw pile so the draw has something to
        // pop. (CardId::Strike is fine — the body only needs *something*
        // to move from draw → hand.)
        let _ = state.add_card_to_draw_pile(crate::Card {
            uid: crate::CardUid::new(u32::MAX).expect("non-zero placeholder"),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: crate::cards::CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        let draw_before = state.player.draw.len();
        let hand_before = state.player.hand.len();

        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);

        assert_eq!(
            state.player.draw.len(),
            draw_before - 1,
            "DarkEmbrace(1) must move one card off the draw pile",
        );
        assert_eq!(
            state.player.hand.len(),
            hand_before + 1,
            "DarkEmbrace(1) must add one card to the hand",
        );
    }

    /// **DarkEmbrace ethereal deferral (bead `sts2-rs-umouk`)**: a
    /// non-ethereal exhaust draws `Amount` immediately, but an
    /// ethereal-caused exhaust (the end-of-turn sweep) draws nothing now —
    /// it bumps `etherealCount` (Power.counter). At AfterTurnEnd(Player)
    /// the batched `Amount * etherealCount` is drawn and the counter
    /// resets. Mirrors C# `DarkEmbracePower.AfterCardExhausted(.., bool
    /// causedByEthereal)` + `AfterTurnEnd(Player)`
    /// (DarkEmbracePower.cs:30-53).
    #[test]
    fn dark_embrace_defers_ethereal_exhaust_to_turn_end() {
        use crate::cards::{CardId, CardType, TargetType};
        let (mut state, de_uid) = state_with_player_power(PowerKind::DarkEmbrace, 1);
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;

        // Seed several cards in the draw pile so each draw has something
        // to pop.
        for _ in 0..6 {
            let _ = state.add_card_to_draw_pile(crate::Card {
                uid: crate::CardUid::new(u32::MAX).expect("non-zero placeholder"),
                card_id: CardId::StrikeIronclad,
                cost: 1,
                card_type: CardType::Attack,
                target_type: TargetType::Enemy,
                upgraded: false,
                base_damage: 6,
                base_block: 0,
                combat_vars: crate::cards::CombatVars::new(),
                enchantments: crate::cards::CardEnchantments::new(),
                tags: crate::cards::CardTags::NONE,
                energy_spent: 0,
                base_replay_count: 0,
                keyword_override: None,
                affliction: None,
            });
        }

        // 1) A non-ethereal exhaust draws 1 immediately.
        let hand_before = state.player.hand.len();
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);
        assert_eq!(
            state.player.hand.len(),
            hand_before + 1,
            "non-ethereal exhaust draws Amount immediately",
        );
        assert_eq!(
            state.powers.get_by_id(de_uid.0).unwrap().counter,
            0,
            "non-ethereal exhaust does NOT bump etherealCount",
        );

        // 2) Two ethereal-caused exhausts (the end-of-turn sweep) draw
        // nothing now and bump etherealCount to 2.
        let hand_after_first = state.player.hand.len();
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), true);
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), true);
        assert_eq!(
            state.player.hand.len(),
            hand_after_first,
            "ethereal-caused exhausts must NOT draw immediately",
        );
        assert_eq!(
            state.powers.get_by_id(de_uid.0).unwrap().counter,
            2,
            "each ethereal-caused exhaust bumps etherealCount",
        );

        // 3) AfterTurnEnd(Player) draws Amount * etherealCount = 1 * 2 = 2
        // and resets the counter.
        let hand_before_turn_end = state.player.hand.len();
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(
            state.player.hand.len(),
            hand_before_turn_end + 2,
            "AfterTurnEnd draws Amount * etherealCount",
        );
        assert_eq!(
            state.powers.get_by_id(de_uid.0).unwrap().counter,
            0,
            "etherealCount resets after the batched turn-end draw",
        );

        // 4) A subsequent AfterTurnEnd with counter == 0 draws nothing.
        let hand_after_reset = state.player.hand.len();
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(
            state.player.hand.len(),
            hand_after_reset,
            "no further draw once etherealCount is 0",
        );
    }

    /// **FeelNoPain is unaffected by the ethereal distinction (bead
    /// `sts2-rs-umouk`)**: FeelNoPain gains block on EVERY exhaust,
    /// whether or not it was caused by ethereal — matching C#
    /// `FeelNoPainPower` (no `causedByEthereal` branch).
    #[test]
    fn feel_no_pain_gains_block_on_ethereal_exhaust() {
        let (mut state, _uid) = state_with_player_power(PowerKind::FeelNoPain, 3);
        let block_before = state.player.block;
        // Ethereal-caused exhaust still grants block.
        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), true);
        assert_eq!(
            state.player.block,
            block_before + 3,
            "FeelNoPain(3) grants block on an ethereal-caused exhaust too",
        );
    }

    /// **`CardCtx` payload**: round-trip the new `card_id` / `card_uid` /
    /// `card_tags` fields through `CardCtx`. Locks the shape so
    /// downstream listeners (Afterimage on-skill, `BoneTea`, …) can key
    /// off identity once their bodies land.
    #[test]
    fn card_ctx_carries_exhausted_card_identity() {
        use crate::cards::{CardId, CardTag, CardTags};
        let card_uid = crate::CardUid::new(7).expect("non-zero");
        let tags = CardTags::one(CardTag::Strike);
        let ctx = CardCtx {
            card_id: Some(CardId::StrikeIronclad),
            card_uid: Some(card_uid),
            card_tags: tags,
            card_type: Some(crate::cards::CardType::Attack),
        };
        assert_eq!(ctx.card_id, Some(CardId::StrikeIronclad));
        assert_eq!(ctx.card_uid, Some(card_uid));
        assert!(ctx.card_tags.contains(CardTag::Strike));
        assert_eq!(ctx.card_type, Some(crate::cards::CardType::Attack));
        // Default round-trip: `CardCtx::default()` carries no identity.
        let empty = CardCtx::default();
        assert_eq!(empty.card_id, None);
        assert_eq!(empty.card_uid, None);
        assert!(empty.card_tags.is_empty());
        assert_eq!(empty.card_type, None);
    }

    /// **`BlockGainedCtx` payload (bead `sts2-rs-6ynt.6.7.1`)**: round-trip
    /// `target` + `amount` through the ctx and confirm the dispatcher
    /// accepts a populated ctx without panic. Locks the shape so the
    /// downstream `GrapplePower` listener (bead `sts2-rs-6ynt.6.7`) can
    /// key off `target == owner` and `amount > 0` when its body lands.
    #[test]
    fn block_gained_ctx_carries_target_and_amount() {
        let ctx = BlockGainedCtx {
            target: CreatureRef::Player,
            amount: 7,
            card_source: None,
        };
        assert!(matches!(ctx.target, CreatureRef::Player));
        assert_eq!(ctx.amount, 7);

        // Default round-trip: still the zero/Player sentinel.
        let empty = BlockGainedCtx::default();
        assert!(matches!(empty.target, CreatureRef::Player));
        assert_eq!(empty.amount, 0);

        // Dispatcher accepts a populated ctx on a state with listeners.
        let mut state = CombatState::default();
        state.player.powers.push(power_uid(1));
        state.relics.push(Relic {
            id: NonZeroU32::new(10).unwrap(),
            kind: RelicKind::BurningBlood,
            counter: 0,
            is_wax: false,
            is_melted: false,
        });
        dispatch_after_block_gained(&mut state, &ctx);
    }

    /// **Empty-bus early-out**: `dispatch_after_block_gained` skips
    /// the listener walks when both `state.powers` and `state.relics`
    /// are empty. Smoke test for the `sts2-rs-4lk9` pattern applied
    /// at this dispatch site.
    #[test]
    fn dispatch_after_block_gained_empty_bus_is_noop() {
        let mut state = CombatState::default();
        assert!(state.powers.is_empty());
        assert!(state.relics.is_empty());
        dispatch_after_block_gained(
            &mut state,
            &BlockGainedCtx {
                target: CreatureRef::Player,
                amount: 5,
                card_source: None,
            },
        );
    }

    /// q6bix F-C: Juggernaut applied to the player's MIRROR Creature
    /// (the realistic `apply_power_to_player` path) must still deal its
    /// on-block-gain damage. The post-walk reaction previously scanned
    /// only legacy `state.player.powers` and silently no-op'd a
    /// mirror-applied Juggernaut.
    #[test]
    fn q6bix_juggernaut_fires_from_mirror_power() {
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 80;
        let player_uid = state.init_player_creature();
        crate::card_effects::apply_power_to_creature(
            &mut state,
            player_uid,
            PowerKind::Juggernaut,
            5,
        );
        assert!(
            state.player.powers.is_empty(),
            "precondition: Juggernaut lives on the mirror, not legacy"
        );
        // Alive enemy in a fresh creature slot.
        let enemy_id = NonZeroU32::new(2).unwrap();
        state.creatures.push(Creature {
            id: enemy_id,
            current_hp: 48,
            max_hp: 48,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid(enemy_id));

        dispatch_after_block_gained(
            &mut state,
            &BlockGainedCtx {
                target: CreatureRef::Player,
                amount: 5,
                card_source: None,
            },
        );

        let enemy_hp = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_id)
            .map(|c| c.current_hp)
            .unwrap();
        assert_eq!(enemy_hp, 43, "Juggernaut(5) must deal 5 to the enemy");
    }

    /// q6bix F-C: FeelNoPain applied to the player's MIRROR Creature must
    /// still gain block on exhaust. Previously scanned legacy only.
    #[test]
    fn q6bix_feel_no_pain_fires_from_mirror_power() {
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 80;
        let player_uid = state.init_player_creature();
        crate::card_effects::apply_power_to_creature(
            &mut state,
            player_uid,
            PowerKind::FeelNoPain,
            2,
        );
        assert!(state.player.powers.is_empty());
        let block_before = state.player.block;

        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);

        assert_eq!(
            state.player.block - block_before,
            2,
            "FeelNoPain(2) must gain 2 block from the mirror"
        );
    }

    /// **Stacked FNP + DE**: both arms fire on a single exhaust.
    /// FeelNoPain(2) + DarkEmbrace(1) → +2 block AND +1 card drawn.
    /// Confirms iteration over `state.player.powers` doesn't
    /// short-circuit after the first match.
    #[test]
    fn feel_no_pain_and_dark_embrace_stack_on_one_exhaust() {
        use crate::cards::{CardId, CardType, TargetType};

        let mut state = CombatState::default();
        // A live player: a dead one makes the combat ending, so draws move no card.
        state.player.current_hp = 80;
        // FeelNoPain(2)
        let fnp_uid = power_uid(1);
        state.powers.push(Power {
            id: fnp_uid.0,
            kind: PowerKind::FeelNoPain,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(fnp_uid);
        // DarkEmbrace(1)
        let de_uid = power_uid(2);
        state.powers.push(Power {
            id: de_uid.0,
            kind: PowerKind::DarkEmbrace,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(de_uid);

        // Seed a draw-pile card so DE has something to draw.
        let _ = state.add_card_to_draw_pile(crate::Card {
            uid: crate::CardUid::new(u32::MAX).expect("non-zero placeholder"),
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: crate::cards::CombatVars::new(),
            enchantments: crate::cards::CardEnchantments::new(),
            tags: crate::cards::CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });

        let block_before = state.player.block;
        let hand_before = state.player.hand.len();

        dispatch_after_card_exhausted(&mut state, &CardCtx::default(), false);

        assert_eq!(state.player.block - block_before, 2, "FNP fires once");
        assert_eq!(state.player.hand.len() - hand_before, 1, "DE fires once");
    }

    // -------------------------------------------------------------------
    // Bead `sts2-rs-zlx.3`: on-attack-played listener bus tests.
    //
    //   - RagePower.after_card_played (Attack → gain block).
    //   - AfterimagePower.after_card_played (any card → gain block).
    //   - PhantomBladesPower.after_card_played (Shiv → counter +=1).
    //   - EnvenomPower.after_damage_given (powered + dmg>0 → Poison).
    // -------------------------------------------------------------------

    /// **Rage arm**: Rage(3) + an Attack-tagged `CardCtx` → +3 player block.
    /// Pin: `card_play_effects.py:146-177`.
    #[test]
    fn rage_grants_block_on_attack_played() {
        use crate::cards::CardType;
        let (mut state, _uid) = state_with_player_power(PowerKind::Rage, 3);
        let starting_block = state.player.block;
        let ctx = CardCtx {
            card_type: Some(CardType::Attack),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);
        assert_eq!(
            state.player.block - starting_block,
            3,
            "Rage(3) must grant +3 block on Attack played",
        );
    }

    /// **Rage filter**: a non-Attack card (Skill / Power / etc.) does
    /// NOT grant block. Mirrors the Python `if card.card_type == ATTACK`
    /// guard.
    #[test]
    fn rage_does_not_grant_block_on_skill_played() {
        use crate::cards::CardType;
        let (mut state, _uid) = state_with_player_power(PowerKind::Rage, 3);
        let starting_block = state.player.block;
        let ctx = CardCtx {
            card_type: Some(CardType::Skill),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);
        assert_eq!(
            state.player.block, starting_block,
            "Rage(3) must NOT fire on a Skill",
        );
    }

    /// **Afterimage arm**: an ARMED Afterimage(1) on the player + a card
    /// played (any type) → +1 block. The arm models C#
    /// `AfterimagePower.BeforeCardPlayed` recording the card (in real combat
    /// `dispatch_before_card_played_powers` sets `counter = 1`); a card that
    /// did not arm the power — e.g. the Afterimage card's own play — grants no
    /// block. The after-play body disarms (`counter -> 0`), so each subsequent
    /// play must re-arm, exactly as the before-play dispatch does.
    #[test]
    fn afterimage_grants_block_on_any_card_played() {
        use crate::cards::CardType;
        let (mut state, uid) = state_with_player_power(PowerKind::Afterimage, 1);
        let arm = |state: &mut CombatState| {
            state.powers.get_mut_by_id(uid.0).unwrap().counter = 1;
        };
        let starting_block = state.player.block;
        // Unarmed (the play that created the power) grants nothing.
        let ctx = CardCtx {
            card_type: Some(CardType::Skill),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);
        assert_eq!(
            state.player.block, starting_block,
            "Unarmed Afterimage (its own creating play) must grant NO block",
        );
        // Skill — armed Afterimage fires on ANY card type.
        arm(&mut state);
        dispatch_after_card_played(&mut state, &ctx);
        assert_eq!(
            state.player.block - starting_block,
            1,
            "Afterimage(1) must grant +1 block on Skill played",
        );
        // Power — also fires (re-armed).
        arm(&mut state);
        let ctx_power = CardCtx {
            card_type: Some(CardType::Power),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx_power);
        assert_eq!(
            state.player.block - starting_block,
            2,
            "Afterimage(1) must grant +1 block on Power played too",
        );
    }

    /// **Afterimage + Rage stack on an Attack**: both fire when an
    /// Attack is played; only Afterimage fires on a Skill.
    #[test]
    fn rage_and_afterimage_stack_on_attack() {
        use crate::cards::CardType;
        let mut state = CombatState::default();
        let rage_uid = power_uid(1);
        state.powers.push(Power {
            id: rage_uid.0,
            kind: PowerKind::Rage,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(rage_uid);
        let after_uid = power_uid(2);
        state.powers.push(Power {
            id: after_uid.0,
            kind: PowerKind::Afterimage,
            // Armed (counter=1), as `dispatch_before_card_played_powers` would
            // for a card played AFTER Afterimage already existed.
            amount: 1,
            counter: 1,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(after_uid);
        let arm_after = |state: &mut CombatState| {
            state.powers.get_mut_by_id(after_uid.0).unwrap().counter = 1;
        };

        let before = state.player.block;
        let attack_ctx = CardCtx {
            card_type: Some(CardType::Attack),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &attack_ctx);
        assert_eq!(
            state.player.block - before,
            3,
            "Rage(2) + Afterimage(1) on an Attack must grant +3 block",
        );

        let mid = state.player.block;
        arm_after(&mut state);
        let skill_ctx = CardCtx {
            card_type: Some(CardType::Skill),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &skill_ctx);
        assert_eq!(
            state.player.block - mid,
            1,
            "Only Afterimage(1) fires on a Skill (Rage filtered out)",
        );
    }

    /// **Shiv counter**: a Shiv-tagged play increments
    /// `state.player.shivs_played_this_turn`; a non-Shiv does not.
    /// C# `PhantomBladesPower.ModifyDamageAdditive` reads
    /// `History.CardPlaysFinished` for "first Shiv this turn".
    #[test]
    fn phantom_blades_increments_shiv_counter() {
        use crate::cards::{CardTag, CardTags, CardType};
        let (mut state, _uid) = state_with_player_power(PowerKind::PhantomBlades, 4);
        assert_eq!(state.player.shivs_played_this_turn, 0);

        // A Shiv-tagged Attack → counter increments.
        let shiv_ctx = CardCtx {
            card_type: Some(CardType::Attack),
            card_tags: CardTags::one(CardTag::Shiv),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &shiv_ctx);
        assert_eq!(
            state.player.shivs_played_this_turn, 1,
            "PhantomBlades must count Shiv plays this turn",
        );

        // A non-Shiv Attack (Strike) → counter does NOT increment.
        let strike_ctx = CardCtx {
            card_type: Some(CardType::Attack),
            card_tags: CardTags::one(CardTag::Strike),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &strike_ctx);
        assert_eq!(
            state.player.shivs_played_this_turn, 1,
            "Strike (non-Shiv) must not bump the Shiv counter",
        );

        // Another Shiv → counter increments again.
        dispatch_after_card_played(&mut state, &shiv_ctx);
        assert_eq!(
            state.player.shivs_played_this_turn, 2,
            "Second Shiv this turn also counts",
        );
    }

    /// Regression (bead `sts2-rs-phantom-blades-shiv-count-j9iug`, Silent mid-fuzz
    /// seed 1172): the per-turn Shiv counter must advance for Shivs played
    /// BEFORE any PhantomBlades exists. C# counts all Shiv plays this turn
    /// from history, so a later Shiv (after PhantomBlades is gained) is NOT
    /// the turn's first Shiv and gets no bonus. The old counter only bumped
    /// while PhantomBlades was present, so those early Shivs went uncounted
    /// and the post-PhantomBlades Shiv wrongly read `== 0`.
    #[test]
    fn shiv_counter_advances_without_phantom_blades_present() {
        use crate::cards::{CardTag, CardTags, CardType};
        let mut state = CombatState::default();
        assert_eq!(state.player.shivs_played_this_turn, 0);
        let shiv_ctx = CardCtx {
            card_type: Some(CardType::Attack),
            card_tags: CardTags::one(CardTag::Shiv),
            ..CardCtx::default()
        };
        // Two Shivs played with NO PhantomBlades power on the player.
        dispatch_after_card_played(&mut state, &shiv_ctx);
        dispatch_after_card_played(&mut state, &shiv_ctx);
        assert_eq!(
            state.player.shivs_played_this_turn, 2,
            "Shivs played without PhantomBlades must still count toward the turn's Shiv total",
        );
    }

    /// **Envenom arm**: Envenom(1) on the player + a powered player
    /// attack dealing >0 damage on an enemy → 1 Poison on the enemy.
    /// Pin: `card_play_effects.py:287-300`.
    #[test]
    fn envenom_applies_poison_on_attack() {
        let mut state = CombatState::default();
        // Envenom(1) on the player.
        let env_uid = power_uid(1);
        state.powers.push(Power {
            id: env_uid.0,
            kind: PowerKind::Envenom,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(env_uid);

        // A single Cultist enemy at uid 2.
        let cultist_id = NonZeroU32::new(2).unwrap();
        state.creatures.push(Creature {
            id: cultist_id,
            current_hp: 48,
            max_hp: 48,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        let cultist_uid = CreatureUid::new(2).unwrap();
        state.enemy_uids.push(cultist_uid);

        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: CreatureRef::Enemy(cultist_uid),
            props: ValueProps::MOVE, // powered
        };
        dispatch_after_damage_given(&mut state, &ctx, 5, 5, false);

        // Cultist should now have a single Poison(1) power.
        let cultist_idx = state
            .creatures
            .iter()
            .position(|c| c.id == cultist_id)
            .expect("cultist present");
        let poison_count: i32 = state.creatures[cultist_idx]
            .powers
            .iter()
            .filter_map(|uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == uid.0 && p.kind == PowerKind::Poison)
                    .map(|p| p.amount)
            })
            .sum();
        assert_eq!(
            poison_count, 1,
            "Envenom(1) must apply 1 Poison to the attacked enemy",
        );
    }

    /// **Envenom on the killing blow**: C# fires `AfterDamageGiven` before
    /// `Kill` (`CreatureCmd.cs:390, :409`) and `CanReceivePowers` admits a
    /// corpse, so the just-killed target still takes the Poison (which an
    /// Outbreak then counts — Silent full-tier seed:1859) before `Kill`
    /// strips it.
    #[test]
    fn envenom_poisons_the_target_its_hit_just_killed() {
        let mut state = CombatState::default();
        let env_uid = power_uid(1);
        state.powers.push(Power {
            id: env_uid.0,
            kind: PowerKind::Envenom,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(env_uid);
        let corpse_id = NonZeroU32::new(2).unwrap();
        state.creatures.push(Creature {
            id: corpse_id,
            current_hp: 0,
            max_hp: 31,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        let corpse_uid = CreatureUid::new(2).unwrap();
        state.enemy_uids.push(corpse_uid);
        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: CreatureRef::Enemy(corpse_uid),
            props: ValueProps::MOVE,
        };
        // Outbreak(11) one application short of its 3rd: the corpse's Poison
        // must count (the AoE fires), and `Kill`'s strip then removes it.
        let ob_uid = power_uid(3);
        state.powers.push(Power {
            id: ob_uid.0,
            kind: PowerKind::Outbreak,
            amount: 11,
            counter: 2,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(ob_uid);
        let bystander_id = NonZeroU32::new(4).unwrap();
        state.creatures.push(Creature {
            id: bystander_id,
            current_hp: 40,
            max_hp: 40,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(4).unwrap());
        dispatch_after_damage_given(&mut state, &ctx, 8, 8, false);
        assert_eq!(
            state.creatures[1].current_hp, 29,
            "the corpse's Poison is Outbreak's 3rd application (11 to the living)"
        );
        let corpse_poisoned = state.creatures[0].powers.iter().any(|uid| {
            state
                .powers
                .iter()
                .any(|p| p.id == uid.0 && p.kind == PowerKind::Poison)
        });
        assert!(!corpse_poisoned, "Kill strips the corpse's Poison");
    }

