    /// **PainfulStabs arm**: a monster carrying PainfulStabs(N) that lands a
    /// powered, unblocked attack on the player adds N Wound cards to the
    /// player's DISCARD pile. C# `PainfulStabsPower.AfterAttack`
    /// (PainfulStabsPower.cs:33-62): `AddToCombatAndPreview<Wound>(player,
    /// PileType.Discard, Amount * num)` where `num` counts the player's
    /// unblocked damage results. Bead `sts2-rs-rb25f`.
    #[test]
    fn painful_stabs_adds_wounds_on_unblocked_attack() {
        use crate::cards::CardId;
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 70;
        state.init_player_creature();
        let enemy_uid = push_painful_stabs_enemy(&mut state, 2);

        let discard_pre = state.player.discard.len();
        let ctx = DamageCtx {
            dealer: CreatureRef::Enemy(enemy_uid),
            target: CreatureRef::Player,
            props: ValueProps::MOVE, // powered
        };
        // unblocked_damage = 6 (>0) → connecting hit.
        dispatch_after_damage_given(&mut state, &ctx, 6, 6, false);
        assert_eq!(
            state.player.discard.len(),
            discard_pre,
            "the Wounds wait for the attack command's end (`AfterAttack`)",
        );
        crate::combat_loop::flush_painful_stabs_wounds(&mut state, enemy_uid);

        assert_eq!(
            state.player.discard.len() - discard_pre,
            2,
            "PainfulStabs(2) must add Amount Wounds per connecting hit",
        );
        for &uid in state.player.discard.iter().rev().take(2) {
            let card = state
                .cards
                .iter()
                .find(|c| c.uid == uid)
                .expect("spawned Wound present in arena");
            assert_eq!(card.card_id, CardId::Wound, "added card is a Wound");
        }
    }

    /// **PainfulStabs predicate**: a fully-blocked powered attack (unblocked
    /// damage == 0) adds NO Wounds. C# gates the per-receiver `num` on
    /// `DamageResult.UnblockedDamage > 0`, so a fully-blocked hit yields
    /// `num == 0` → zero Wounds. Bead `sts2-rs-rb25f`.
    #[test]
    fn painful_stabs_skips_fully_blocked_attack() {
        let mut state = CombatState::default();
        state.player.current_hp = 70;
        state.player.max_hp = 70;
        state.init_player_creature();
        let enemy_uid = push_painful_stabs_enemy(&mut state, 2);

        let discard_pre = state.player.discard.len();
        let ctx = DamageCtx {
            dealer: CreatureRef::Enemy(enemy_uid),
            target: CreatureRef::Player,
            props: ValueProps::MOVE, // powered
        };
        // unblocked_damage = 0 → fully blocked, no Wound.
        dispatch_after_damage_given(&mut state, &ctx, 0, 6, true);
        crate::combat_loop::flush_painful_stabs_wounds(&mut state, enemy_uid);

        assert_eq!(
            state.player.discard.len(),
            discard_pre,
            "PainfulStabs must not add Wounds on a fully-blocked hit",
        );
    }

    // -------------------------------------------------------------------
    // Bead `sts2-rs-zlx.4`: turn-start power tick bus
    //
    // Smoke-tests for the listener bodies wired in this bead:
    //   - DemonFormPower.after_side_turn_start (+Strength on owner)
    //   - NoxiousFumesPower.after_side_turn_start (Poison every enemy)
    //   - StormPower.after_card_played (channel Lightning when Power)
    // -------------------------------------------------------------------

    /// **`DemonForm`**: at the start of the owner's turn, the player gains
    /// `amount` Strength via `Effect::ApplyPower`. Pin
    /// `turn_effects.py:31-46`.
    #[test]
    fn demon_form_grants_strength_on_player_turn_start() {
        let mut state = CombatState::default();
        // Give the player non-zero HP so the mirror Creature is alive
        // (otherwise `apply_power_to_creature` short-circuits on its
        // `current_hp > 0` guard).
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        // Player mirror Creature so `Effect::ApplyPower` can route the
        // Strength application.
        let player_uid = state.init_player_creature();
        let demon_uid = power_uid(1);
        state.powers.push(Power {
            id: demon_uid.0,
            kind: PowerKind::DemonForm,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(demon_uid);

        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });

        // Expect Strength(2) on the player mirror Creature.
        let player_creature = state
            .creatures
            .iter()
            .find(|c| c.id == player_uid.0)
            .expect("player mirror present");
        let strength: i32 = player_creature
            .powers
            .iter()
            .filter_map(|uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == uid.0 && p.kind == PowerKind::Strength)
                    .map(|p| p.amount)
            })
            .sum();
        assert_eq!(
            strength, 2,
            "DemonForm(2) must grant +2 Strength at turn start"
        );
    }

