    /// **`PrepTime`** (C# `PrepTimePower.AfterSideTurnStart`,
    /// `PrepTimePower.cs:14-20`): on the owning player's turn start, grants
    /// Vigor=Amount. PrepTime is a Counter Buff with NO decrement, so it
    /// re-grants every owning-side turn and persists. Two dispatch cycles
    /// must accumulate Vigor (4 -> 8) and leave the PrepTime instance intact.
    /// Closes coverage divergence `card:PREP_TIME` (player.powers.len cs3/rs2).
    #[test]
    fn prep_time_grants_vigor_each_player_turn_start_and_persists() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let player_uid = state.init_player_creature();
        let prep_uid = power_uid(1);
        state.powers.push(Power {
            id: prep_uid.0,
            kind: PowerKind::PrepTime,
            amount: 4,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(prep_uid);

        let vigor_amount = |state: &CombatState| -> i32 {
            let pc = state
                .creatures
                .iter()
                .find(|c| c.id == player_uid.0)
                .expect("player mirror present");
            pc.powers
                .iter()
                .filter_map(|uid| {
                    state
                        .powers
                        .iter()
                        .find(|p| p.id == uid.0 && p.kind == PowerKind::Vigor)
                        .map(|p| p.amount)
                })
                .sum()
        };
        let prep_time_present = |state: &CombatState| -> bool {
            state.powers.iter().any(|p| p.kind == PowerKind::PrepTime)
        };

        // First player turn start: Vigor(4) granted, PrepTime persists.
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(vigor_amount(&state), 4, "PrepTime(4) must grant +4 Vigor");
        assert!(
            prep_time_present(&state),
            "PrepTime must NOT remove itself after granting Vigor"
        );

        // Second player turn start: re-grants (no decrement) -> Vigor 8.
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(
            vigor_amount(&state),
            8,
            "PrepTime must re-grant Vigor every owning-side turn (4 -> 8)"
        );
        assert!(
            prep_time_present(&state),
            "PrepTime must still persist after the second grant"
        );
    }

    /// **`BiasedCognition`** (C# `BiasedCognitionPower.AfterSideTurnStart`):
    /// on the owning player's turn start, applies `-Amount` Focus. The power
    /// is a Counter Debuff that never decrements itself, so it bleeds Focus
    /// every owning-side turn. Starting Focus(4) + BiasedCognition(1) must
    /// decay to Focus 3 then 2 across two player turn starts, with the
    /// BiasedCognition instance persisting.
    #[test]
    fn biased_cognition_bleeds_one_focus_each_player_turn_start() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let player_uid = state.init_player_creature();
        let focus_uid = power_uid(1);
        state.powers.push(Power {
            id: focus_uid.0,
            kind: PowerKind::Focus,
            amount: 4,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(focus_uid);
        let bc_uid = power_uid(2);
        state.powers.push(Power {
            id: bc_uid.0,
            kind: PowerKind::BiasedCognition,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(bc_uid);

        let focus_amount = |state: &CombatState| -> i32 {
            state
                .powers
                .iter()
                .filter(|p| p.kind == PowerKind::Focus)
                .map(|p| p.amount)
                .sum()
        };
        let bc_present = |state: &CombatState| -> bool {
            state
                .powers
                .iter()
                .any(|p| p.kind == PowerKind::BiasedCognition)
        };

        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(focus_amount(&state), 3, "Focus(4) bleeds to 3");
        assert!(bc_present(&state), "BiasedCognition persists");

        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(focus_amount(&state), 2, "Focus bleeds 3 -> 2");
        assert!(bc_present(&state), "BiasedCognition still persists");
        let _ = player_uid;
    }

