    /// **`NoxiousFumes`**: at the start of the player's turn, every alive
    /// enemy in `state.enemy_uids` receives `amount` Poison. Pin
    /// `turn_effects.py:90-108`.
    #[test]
    fn noxious_fumes_poisons_all_alive_enemies_on_player_turn_start() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let _player_uid = state.init_player_creature();
        let nf_uid = power_uid(1);
        state.powers.push(Power {
            id: nf_uid.0,
            kind: PowerKind::NoxiousFumes,
            amount: 2,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(nf_uid);

        // Two enemies — one alive, one dead. Only the alive one should be
        // poisoned.
        let alive_id = NonZeroU32::new(10).unwrap();
        state.creatures.push(Creature {
            id: alive_id,
            current_hp: 30,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(10).unwrap());

        let dead_id = NonZeroU32::new(11).unwrap();
        state.creatures.push(Creature {
            id: dead_id,
            current_hp: 0,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(11).unwrap());

        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });

        let alive_idx = state
            .creatures
            .iter()
            .position(|c| c.id == alive_id)
            .expect("alive enemy present");
        let alive_poison: i32 = state.creatures[alive_idx]
            .powers
            .iter()
            .filter_map(|uid| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == uid.0 && p.kind == PowerKind::Poison)
                    .map(|p| p.amount)
            })
            .sum();
        assert_eq!(
            alive_poison, 2,
            "NoxiousFumes(2) must apply 2 Poison to alive enemy"
        );

        let dead_idx = state
            .creatures
            .iter()
            .position(|c| c.id == dead_id)
            .expect("dead enemy present");
        assert!(
            state.creatures[dead_idx].powers.is_empty(),
            "NoxiousFumes must skip dead enemies",
        );
    }

    /// **`Rampart`** (`sts2-rs-ybtmu`): LivingShield's enemy-owned Rampart(25)
    /// re-grants 25 block to each living TurretOperator enemy at PLAYER
    /// turn-start. The LivingShield owner itself (and dead turrets) gain
    /// nothing. Mirrors C# `RampartPower.AfterSideTurnStart`.
    #[test]
    fn rampart_grants_block_to_turret_operators_on_player_turn_start() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let _player_uid = state.init_player_creature();

        // LivingShield enemy carrying Rampart(25).
        let rampart_uid = power_uid(1);
        state.powers.push(Power {
            id: rampart_uid.0,
            kind: PowerKind::Rampart,
            amount: 25,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        let shield_id = NonZeroU32::new(10).unwrap();
        state.creatures.push(Creature {
            id: shield_id,
            current_hp: 55,
            max_hp: 55,
            block: 0,
            powers: SmallVec::from_buf_and_len([rampart_uid; 8], 1),
            species: Some(MonsterKind::LivingShield),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("LivingShield"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(10).unwrap());

        // Alive TurretOperator — should gain 25 block.
        let turret_id = NonZeroU32::new(11).unwrap();
        state.creatures.push(Creature {
            id: turret_id,
            current_hp: 41,
            max_hp: 41,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::TurretOperator),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("TurretOperator"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(11).unwrap());

        // Dead TurretOperator — should be skipped.
        let dead_turret_id = NonZeroU32::new(12).unwrap();
        state.creatures.push(Creature {
            id: dead_turret_id,
            current_hp: 0,
            max_hp: 41,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::TurretOperator),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("TurretOperator"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(12).unwrap());

        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });

        let block_of = |id: NonZeroU32| {
            state
                .creatures
                .iter()
                .find(|c| c.id == id)
                .map_or(0, |c| c.block)
        };
        assert_eq!(
            block_of(turret_id),
            25,
            "alive TurretOperator gains 25 block"
        );
        assert_eq!(block_of(dead_turret_id), 0, "dead TurretOperator skipped");
        assert_eq!(
            block_of(shield_id),
            0,
            "Rampart owner gains no block itself"
        );
    }

    /// **`Rampart` extra-turn gate**: C# `RampartPower.AfterSideTurnStart`
    /// also returns early while `PlayersTakingExtraTurn.Count > 0`
    /// (RampartPower.cs:22-30), so a PaelsEye extra turn does not stack a
    /// second 25 on the turret (Necrobinder seed 1006: cs=25, rs=50).
    #[test]
    fn rampart_skips_extra_player_turn() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let _player_uid = state.init_player_creature();

        let rampart_uid = power_uid(1);
        state.powers.push(Power {
            id: rampart_uid.0,
            kind: PowerKind::Rampart,
            amount: 25,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.creatures.push(Creature {
            id: NonZeroU32::new(10).unwrap(),
            current_hp: 55,
            max_hp: 55,
            block: 0,
            powers: SmallVec::from_buf_and_len([rampart_uid; 8], 1),
            species: Some(MonsterKind::LivingShield),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("LivingShield"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(10).unwrap());
        let turret_id = NonZeroU32::new(11).unwrap();
        state.creatures.push(Creature {
            id: turret_id,
            current_hp: 41,
            max_hp: 41,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::TurretOperator),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("TurretOperator"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(11).unwrap());
        let block_of = |state: &CombatState| {
            state
                .creatures
                .iter()
                .find(|c| c.id == turret_id)
                .map_or(0, |c| c.block)
        };

        // Turn 1: Rampart grants 25.
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(block_of(&state), 25);

        // Extra turn: no re-grant, the turn-1 block stays at 25.
        state.combat_log.taking_extra_turn = true;
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(block_of(&state), 25, "no Rampart grant on an extra turn");

        // Next normal turn (flag cleared at end of turn): grants again.
        state.combat_log.taking_extra_turn = false;
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(block_of(&state), 50);
    }

    /// C# `PlatingPower.AfterSideTurnStart` ticks a player's Plating at every
    /// player turn start after turn 1, a PaelsEye extra turn included. Rust
    /// ticks at the enemy turn end, so only the extra turn ticks here (act23
    /// Necrobinder:1006: C# 3 -> 2, Rust stayed at 3).
    #[test]
    fn player_plating_ticks_at_an_extra_turn_start_only() {
        let (mut state, uid) = state_with_player_power(PowerKind::Plating, 3);
        let amount = |s: &CombatState| s.powers.get_by_id(uid.0).map_or(0, |p| p.amount);
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(
            amount(&state),
            3,
            "a normal turn start leaves it to the enemy turn end"
        );
        state.combat_log.taking_extra_turn = true;
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });
        assert_eq!(amount(&state), 2);
    }

