    /// Build a two-arm KaiserCrab scenario: Crusher (uid 10, BackAttackLeft +
    /// CrabRage) and Rocket (uid 11, BackAttackRight + CrabRage), with the
    /// player holding Surrounded (uid `surrounded_pid`, facing Right). Power
    /// uids: 1=Crusher CrabRage, 2=Crusher BackAttackLeft, 3=Rocket CrabRage,
    /// 4=Rocket BackAttackRight, 5=player Surrounded.
    #[cfg(test)]
    fn kaiser_crab_scenario() -> CombatState {
        let mut state = CombatState::default();
        state.player.current_hp = 60;
        state.player.max_hp = 60;
        let _player_uid = state.init_player_creature();

        let mk_power = |kind: PowerKind, id: u32, counter: i32| Power {
            id: NonZeroU32::new(id).unwrap(),
            kind,
            amount: 1,
            counter,
            applier: None,
            skip_next_tick: false,
        };
        state.powers.push(mk_power(PowerKind::CrabRage, 1, 0));
        state.powers.push(mk_power(PowerKind::BackAttackLeft, 2, 0));
        state.powers.push(mk_power(PowerKind::CrabRage, 3, 0));
        state
            .powers
            .push(mk_power(PowerKind::BackAttackRight, 4, 0));
        // Surrounded facing Right (counter == SURROUNDED_FACING_RIGHT == 0).
        state
            .powers
            .push(mk_power(PowerKind::Surrounded, 5, SURROUNDED_FACING_RIGHT));

        // Crusher (CrabRage + BackAttackLeft).
        let mut crusher_powers: SmallVec<[crate::PowerUid; 8]> = SmallVec::new();
        crusher_powers.push(power_uid(1));
        crusher_powers.push(power_uid(2));
        state.creatures.push(Creature {
            id: NonZeroU32::new(10).unwrap(),
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: crusher_powers,
            species: Some(MonsterKind::Crusher),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("Crusher"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(10).unwrap());

        // Rocket (CrabRage + BackAttackRight).
        let mut rocket_powers: SmallVec<[crate::PowerUid; 8]> = SmallVec::new();
        rocket_powers.push(power_uid(3));
        rocket_powers.push(power_uid(4));
        state.creatures.push(Creature {
            id: NonZeroU32::new(11).unwrap(),
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: rocket_powers,
            species: Some(MonsterKind::Rocket),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("Rocket"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(11).unwrap());

        // Surrounded is a player-owned debuff in this encounter.
        state.player.powers.push(power_uid(5));
        if let Some(puid) = state.player.creature_uid {
            if let Some(c) = state.creatures.iter_mut().find(|c| c.id == puid.0) {
                c.powers.push(power_uid(5));
            }
        }
        state
    }

    /// **`CrabRage.AfterDeath`** (`sts2-rs-ybtmu`): when one KaiserCrab arm
    /// dies, the surviving arm gains +6 Strength and +99 block and consumes
    /// its CrabRage. The dead arm's own CrabRage does NOT re-fire.
    #[test]
    fn crab_rage_enrages_surviving_arm_on_partner_death() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();
        let rocket = CreatureUid::new(11).unwrap();

        // Rocket dies; Crusher should enrage.
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == rocket.0) {
            c.current_hp = 0;
        }
        dispatch_after_death(
            &mut state,
            &AfterDeathCtx {
                dead: rocket,
                dead_side: Side::Enemy,
            },
        );

        let crusher_c = state.creatures.iter().find(|c| c.id == crusher.0).unwrap();
        let crusher_str: i32 = crusher_c
            .powers
            .iter()
            .filter_map(|u| {
                state
                    .powers
                    .iter()
                    .find(|p| p.id == u.0 && p.kind == PowerKind::Strength)
                    .map(|p| p.amount)
            })
            .sum();
        assert_eq!(crusher_str, 6, "surviving arm gains +6 Strength");
        assert_eq!(crusher_c.block, 99, "surviving arm gains +99 block");
        assert!(
            !crusher_c.powers.iter().any(|u| state
                .powers
                .iter()
                .any(|p| p.id == u.0 && p.kind == PowerKind::CrabRage)),
            "surviving arm's CrabRage is consumed after firing"
        );
    }

    /// An AoE that kills one KaiserCrab arm hits the other BEFORE CrabRage
    /// shields it: C# kills the felled targets only after the whole
    /// `CreatureCmd.Damage` (CreatureCmd.cs:351-409). Regent act23 seed 1010
    /// (Black Hole's star damage).
    #[test]
    fn aoe_kill_enrages_partner_only_after_every_hit_lands() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();
        let rocket = CreatureUid::new(11).unwrap();
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == crusher.0) {
            c.current_hp = 3;
        }
        crate::card_effects::deal_damage_to_all_alive_enemies(
            &mut state,
            3,
            ValueProps::UNPOWERED,
            None,
        );
        let rocket_c = state.creatures.iter().find(|c| c.id == rocket.0).unwrap();
        assert_eq!(
            rocket_c.current_hp, 97,
            "the hit landed before the rage block"
        );
        assert_eq!(rocket_c.block, 99, "CrabRage still fired after the batch");
    }

    /// Inferno's fan-out is ONE multi-target `CreatureCmd.Damage`
    /// (`InfernoPower.cs:48`), so a crab arm it kills dies only after the
    /// sibling took its hit (`CreatureCmd.cs:394-431` batches the kills):
    /// the survivor ends at hp-9 with 99 block, not untouched behind it
    /// (act23 Ironclad:2122, CrimsonMantle self-damage at turn start).
    #[test]
    fn inferno_fan_kill_enrages_partner_only_after_every_hit_lands() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();
        let rocket = CreatureUid::new(11).unwrap();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        state.side = Side::Player;
        let puid = state.player.creature_uid.unwrap();
        crate::card_effects::apply_power_to_creature(&mut state, puid, PowerKind::Inferno, 9);
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == crusher.0) {
            c.current_hp = 9;
        }
        let ctx = DamageCtx {
            dealer: CreatureRef::Player,
            target: CreatureRef::Player,
            props: ValueProps::UNPOWERED,
        };
        dispatch_after_damage_received(&mut state, &ctx, 1);
        let crusher_c = state.creatures.iter().find(|c| c.id == crusher.0).unwrap();
        assert_eq!(crusher_c.current_hp, 0, "the fan-out killed the Crusher");
        let rocket_c = state.creatures.iter().find(|c| c.id == rocket.0).unwrap();
        assert_eq!(
            rocket_c.current_hp, 91,
            "the hit landed before the rage block"
        );
        assert_eq!(rocket_c.block, 99, "CrabRage still fired after the batch");
    }

    /// **`CrabRage` side gate** (`sts2-rs-ybtmu`): a power never enrages off
    /// its own owner's death (the dead owner cannot react).
    #[test]
    fn crab_rage_does_not_fire_for_own_death() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();

        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == crusher.0) {
            c.current_hp = 0;
        }
        dispatch_after_death(
            &mut state,
            &AfterDeathCtx {
                dead: crusher,
                dead_side: Side::Enemy,
            },
        );

        // Crusher is the dead one — its CrabRage must not enrage itself, and
        // Rocket (still alive) gains Str/Block from Crusher's death.
        let crusher_c = state.creatures.iter().find(|c| c.id == crusher.0).unwrap();
        assert_eq!(crusher_c.block, 0, "dead arm does not enrage itself");
        let rocket_c = state
            .creatures
            .iter()
            .find(|c| c.id == NonZeroU32::new(11).unwrap())
            .unwrap();
        assert_eq!(
            rocket_c.block, 99,
            "the LIVING partner enrages off the death"
        );
    }

    /// **`update_surrounded_facing`** (`sts2-rs-ybtmu`): aiming a card at the
    /// left arm (BackAttackLeft) while facing Right turns the player to face
    /// Left; aiming at the right arm (BackAttackRight) while facing Left turns
    /// back to Right.
    #[test]
    fn surrounded_facing_flips_toward_card_target() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();
        let rocket = CreatureUid::new(11).unwrap();
        let facing = |s: &CombatState| {
            s.powers
                .iter()
                .find(|p| p.kind == PowerKind::Surrounded)
                .map(|p| p.counter)
                .unwrap()
        };
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_RIGHT,
            "starts facing Right"
        );

        // Attack the left arm (Crusher) → face Left.
        update_surrounded_facing(&mut state, crusher);
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_LEFT,
            "faces Left after targeting Crusher"
        );

        // Attack the left arm again → no change (already facing Left).
        update_surrounded_facing(&mut state, crusher);
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_LEFT,
            "stays Left targeting Crusher again"
        );

        // Attack the right arm (Rocket) → face Right.
        update_surrounded_facing(&mut state, rocket);
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_RIGHT,
            "faces Right after targeting Rocket"
        );
    }

    /// C# strips a corpse's powers on kill (`CreatureCmd.Kill` ->
    /// `RemoveAllPowersAfterDeath`, CreatureCmd.cs:533 v0.107.1 / :566
    /// v0.111.0; BackAttackLeft/Right keep the default removal), so a card
    /// auto-played at an already-dead arm finds no BackAttack power in
    /// `SurroundedPower.UpdateDirection` and the player keeps facing. Rust
    /// keeps corpse powers, so the dead arm must be skipped explicitly
    /// (loadout Silent 5070 v0.111.0: Knife Trap's 2nd Shiv at the dead
    /// Rocket flipped the facing back).
    #[test]
    fn surrounded_ignores_a_dead_target() {
        let mut state = kaiser_crab_scenario();
        let crusher = CreatureUid::new(10).unwrap();
        let rocket = CreatureUid::new(11).unwrap();
        let facing = |s: &CombatState| {
            s.powers
                .iter()
                .find(|p| p.kind == PowerKind::Surrounded)
                .map(|p| p.counter)
                .unwrap()
        };
        update_surrounded_facing(&mut state, crusher);
        assert_eq!(facing(&state), SURROUNDED_FACING_LEFT);
        // Rocket (BackAttackRight) is dead but keeps its powers in Rust.
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == rocket.0) {
            c.current_hp = 0;
        }
        update_surrounded_facing(&mut state, rocket);
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_LEFT,
            "a dead target has no BackAttack power in C#"
        );
    }

    /// **`Surrounded.AfterDeath`** (`sts2-rs-ybtmu`): when one arm dies and
    /// every remaining hittable enemy shares a single back-attack side, the
    /// player turns to face the survivor (no back-attack is possible any more).
    #[test]
    fn surrounded_refaces_when_one_arm_dies() {
        let mut state = kaiser_crab_scenario();
        let rocket = CreatureUid::new(11).unwrap();
        let facing = |s: &CombatState| {
            s.powers
                .iter()
                .find(|p| p.kind == PowerKind::Surrounded)
                .map(|p| p.counter)
                .unwrap()
        };
        assert_eq!(facing(&state), SURROUNDED_FACING_RIGHT);

        // Rocket dies → only Crusher (BackAttackLeft) remains hittable; facing
        // Right + a BackAttackLeft target ⇒ flip to Left.
        if let Some(c) = state.creatures.iter_mut().find(|c| c.id == rocket.0) {
            c.current_hp = 0;
        }
        dispatch_after_death(
            &mut state,
            &AfterDeathCtx {
                dead: rocket,
                dead_side: Side::Enemy,
            },
        );
        assert_eq!(
            facing(&state),
            SURROUNDED_FACING_LEFT,
            "player re-faces toward the lone surviving arm"
        );
    }

    /// Build a minimal Tunneler-shaped AI (BELOW self-loop / DIZZY_MOVE stun
    /// → BITE / BITE) for the block-break channel tests. Mirrors the real
    /// `create_tunneler_ai` graph closely enough to exercise the
    /// `ForceMonsterMove → DIZZY_MOVE` redirect without depending on
    /// `sts2-content`.
    #[cfg(test)]
    fn minimal_tunneler_ai() -> crate::monster_ai::MonsterAi {
        use crate::monster_ai::{MonsterState, MoveState};
        use crate::monsters::Intent;
        fn noop(_: &mut CombatState, _: CreatureUid) {}
        let mk = |id: &'static str, intent: Intent, follow: &'static str| {
            let mut intents: SmallVec<[Intent; 4]> = SmallVec::new();
            intents.push(intent);
            MonsterState::Move(MoveState {
                id,
                effect: noop,
                intents,
                follow_up: Some(follow),
                must_perform_once: false,
            })
        };
        let mut states = std::collections::BTreeMap::new();
        states.insert(
            "BELOW_MOVE_1",
            mk(
                "BELOW_MOVE_1",
                Intent::Attack { damage: 23 },
                "BELOW_MOVE_1",
            ),
        );
        states.insert("DIZZY_MOVE", mk("DIZZY_MOVE", Intent::Stun, "BITE_MOVE"));
        states.insert(
            "BITE_MOVE",
            mk("BITE_MOVE", Intent::Attack { damage: 13 }, "BURROW_MOVE"),
        );
        states.insert(
            "BURROW_MOVE",
            mk(
                "BURROW_MOVE",
                Intent::Buff {
                    kind: PowerKind::Burrowed,
                    amount: 1,
                },
                "BELOW_MOVE_1",
            ),
        );
        crate::monster_ai::MonsterAi::new(states, "BELOW_MOVE_1")
    }

    /// Spawn a burrowed Tunneler (uid 10) telegraphing BELOW, holding a
    /// Burrowed power (uid 1) and `block`. The player is initialised so the
    /// owner/side guards resolve.
    #[cfg(test)]
    fn burrowed_tunneler_state(block: i32) -> CombatState {
        let mut state = CombatState::default();
        state.player.current_hp = 60;
        state.player.max_hp = 60;
        let _ = state.init_player_creature();

        state.powers.push(Power {
            id: NonZeroU32::new(1).unwrap(),
            kind: PowerKind::Burrowed,
            amount: 1,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        let mut powers: SmallVec<[crate::PowerUid; 8]> = SmallVec::new();
        powers.push(power_uid(1));
        let mut ai = minimal_tunneler_ai();
        ai.set_owner(CreatureUid::new(10).unwrap());
        state.creatures.push(Creature {
            id: NonZeroU32::new(10).unwrap(),
            current_hp: 87,
            max_hp: 87,
            block,
            powers,
            species: Some(MonsterKind::Tunneler),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("Tunneler"),
            ai: Some(ai),
        });
        state.enemy_uids.push(CreatureUid::new(10).unwrap());
        state
    }

    /// **`Burrowed.AfterBlockBroken`** (`sts2-rs-ybtmu`, Group A): when the
    /// burrowed Tunneler's own block breaks, it is redirected to `DIZZY_MOVE`
    /// (stun) immediately and loses Burrowed.
    #[test]
    fn burrowed_block_broken_stuns_owner_and_removes_power() {
        let mut state = burrowed_tunneler_state(0);
        let tunneler = CreatureUid::new(10).unwrap();

        // Pre-condition: telegraphing BELOW, has Burrowed.
        let ai_move = |s: &CombatState| {
            s.creatures
                .iter()
                .find(|c| c.id == tunneler.0)
                .and_then(|c| c.ai.as_ref())
                .map(crate::monster_ai::MonsterAi::current_state_id)
                .unwrap()
        };
        assert_eq!(ai_move(&state), "BELOW_MOVE_1");

        dispatch_after_block_broken(
            &mut state,
            &AfterBlockBrokenCtx {
                broken: tunneler,
                breaker: None,
            },
        );

        assert_eq!(
            ai_move(&state),
            "DIZZY_MOVE",
            "broken shell → unburrow → stunned (DIZZY_MOVE) immediately",
        );
        let still_burrowed = state
            .creatures
            .iter()
            .find(|c| c.id == tunneler.0)
            .unwrap()
            .powers
            .iter()
            .any(|u| {
                state
                    .powers
                    .iter()
                    .any(|p| p.id == u.0 && p.kind == PowerKind::Burrowed)
            });
        assert!(!still_burrowed, "Burrowed is removed on block-break");
    }

    /// The channel is owner-scoped: a *different* creature's block breaking
    /// must NOT stun the burrowed Tunneler (C# `if (creature == Owner)`).
    #[test]
    fn burrowed_ignores_other_creatures_block_break() {
        let mut state = burrowed_tunneler_state(0);
        let tunneler = CreatureUid::new(10).unwrap();
        let player_uid = state.player.creature_uid.unwrap();

        dispatch_after_block_broken(
            &mut state,
            &AfterBlockBrokenCtx {
                broken: player_uid,
                breaker: None,
            },
        );

        let c = state.creatures.iter().find(|c| c.id == tunneler.0).unwrap();
        assert_eq!(
            c.ai.as_ref().unwrap().current_state_id(),
            "BELOW_MOVE_1",
            "another creature's break leaves the Tunneler's move untouched",
        );
        assert!(
            c.powers.iter().any(|u| state
                .powers
                .iter()
                .any(|p| p.id == u.0 && p.kind == PowerKind::Burrowed)),
            "Burrowed survives an unrelated block-break",
        );
    }

    /// **Storm**: when a Power card is played, channel the Storm stacks held
    /// BEFORE that play (the `BeforeCardPlayed` snapshot). C# `StormPower`
    /// (StormPower.cs:42-64). The snapshot is armed by
    /// [`arm_storm_snapshot`]; without arming, nothing channels.
    #[test]
    fn storm_channels_snapshot_lightning_on_power_played() {
        use crate::cards::CardType;
        use crate::orbs::{Orb, OrbSlots};

        let (mut state, _) = state_with_player_power(PowerKind::Storm, 2);
        // Defect baseline belt so the channeled orbs land somewhere.
        state.player.orbs = OrbSlots::with_default_capacity();

        // Arm the before-play snapshot (Storm == 2 before this card resolves).
        arm_storm_snapshot(&mut state);

        let ctx = CardCtx {
            card_type: Some(CardType::Power),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);

        let lightning_count = state
            .player
            .orbs
            .slots
            .iter()
            .filter(|o| matches!(o, Orb::Lightning))
            .count();
        assert_eq!(
            lightning_count, 2,
            "Storm(2) must channel 2 Lightning orbs (the before-play snapshot)",
        );
    }

    /// **Storm self-apply**: a Storm instance that was NOT armed at
    /// before-play (its `counter` is 0 — modelling Storm applied DURING the
    /// current card's `OnPlay`, i.e. the Storm card's own play) channels 0.
    /// This is the C# "the applying card isn't in `amountsForPlayedCards` yet"
    /// behaviour and the fix for the over-channel that desynced
    /// `combat_targets` at end of turn.
    #[test]
    fn storm_does_not_channel_on_its_own_application() {
        use crate::cards::CardType;
        use crate::orbs::{Orb, OrbSlots};

        let (mut state, _) = state_with_player_power(PowerKind::Storm, 1);
        state.player.orbs = OrbSlots::with_default_capacity();
        // Deliberately do NOT arm: the Storm instance is "freshly applied" this
        // play, so its transient snapshot counter is 0.
        for p in &mut state.powers {
            if p.kind == PowerKind::Storm {
                p.counter = 0;
            }
        }

        let ctx = CardCtx {
            card_type: Some(CardType::Power),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);

        let lightning_count = state
            .player
            .orbs
            .slots
            .iter()
            .filter(|o| matches!(o, Orb::Lightning))
            .count();
        assert_eq!(
            lightning_count, 0,
            "Storm applied during this play (unarmed) must channel 0 on that play",
        );
    }

    /// **Storm filter**: a non-Power card (Attack / Skill) does NOT
    /// channel Lightning. Mirrors the Python `if card_type == POWER`
    /// guard.
    #[test]
    fn storm_does_not_channel_on_attack() {
        use crate::cards::CardType;
        use crate::orbs::{Orb, OrbSlots};

        let (mut state, _) = state_with_player_power(PowerKind::Storm, 2);
        state.player.orbs = OrbSlots::with_default_capacity();

        let ctx = CardCtx {
            card_type: Some(CardType::Attack),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);

        let lightning_count = state
            .player
            .orbs
            .slots
            .iter()
            .filter(|o| matches!(o, Orb::Lightning))
            .count();
        assert_eq!(
            lightning_count, 0,
            "Storm must NOT channel on an Attack-typed card",
        );
    }

    /// **`HailstormPower` fixture (`sts2-rs-rnv6`)**: with `Hailstorm(5)`
    /// on the player and exactly one `Frost` orb in the belt, the
    /// `before_turn_end` dispatcher must deal 5 unpowered damage to
    /// every alive enemy (skipping dead enemies). Mirrors Python
    /// `sts2-rl-agent@01c094d:sts2_env/powers/remaining_b.py:108-150`
    /// (`HailstormPower.before_turn_end`).
    #[test]
    fn hailstorm_damages_all_alive_enemies_on_player_before_turn_end() {
        use crate::orbs::{Orb, OrbSlots};

        let (mut state, _) = state_with_player_power(PowerKind::Hailstorm, 5);
        // Channel a single Frost orb — threshold is `>= 1`.
        state.player.orbs = OrbSlots::with_default_capacity();
        crate::orbs::channel_orb(&mut state, Orb::Frost);

        // Two enemies: one alive (HP 30), one dead (HP 0). Only the alive
        // enemy should take 5 damage; the dead enemy should be skipped.
        let alive_id = NonZeroU32::new(20).unwrap();
        state.creatures.push(Creature {
            id: alive_id,
            current_hp: 30,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(20).unwrap());

        let dead_id = NonZeroU32::new(21).unwrap();
        state.creatures.push(Creature {
            id: dead_id,
            current_hp: 0,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(21).unwrap());

        // Second alive enemy at HP 30 to confirm "every alive enemy" not
        // just the first one.
        let other_id = NonZeroU32::new(22).unwrap();
        state.creatures.push(Creature {
            id: other_id,
            current_hp: 30,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(22).unwrap());

        dispatch_before_turn_end(&mut state, &TurnSideCtx { side: Side::Player });

        let alive_hp = state
            .creatures
            .iter()
            .find(|c| c.id == alive_id)
            .map(|c| c.current_hp)
            .expect("alive enemy present");
        assert_eq!(
            alive_hp, 25,
            "Hailstorm(5) must deal 5 damage to the first alive enemy"
        );

        let other_hp = state
            .creatures
            .iter()
            .find(|c| c.id == other_id)
            .map(|c| c.current_hp)
            .expect("second alive enemy present");
        assert_eq!(
            other_hp, 25,
            "Hailstorm(5) must deal 5 damage to every alive enemy"
        );

        let dead_hp = state
            .creatures
            .iter()
            .find(|c| c.id == dead_id)
            .map(|c| c.current_hp)
            .expect("dead enemy present");
        assert_eq!(dead_hp, 0, "Hailstorm must skip dead enemies");
    }

    /// **`HailstormPower` no-Frost gate (`sts2-rs-rnv6`)**: with
    /// `Hailstorm(5)` and an empty (or Frost-less) orb belt, the
    /// `before_turn_end` walk must short-circuit and deal zero damage.
    #[test]
    fn hailstorm_skips_when_no_frost_orb_present() {
        use crate::orbs::{Orb, OrbSlots};

        let (mut state, _) = state_with_player_power(PowerKind::Hailstorm, 5);
        state.player.orbs = OrbSlots::with_default_capacity();
        // Channel a Lightning orb — does NOT satisfy the Frost threshold.
        crate::orbs::channel_orb(&mut state, Orb::Lightning);

        let alive_id = NonZeroU32::new(30).unwrap();
        state.creatures.push(Creature {
            id: alive_id,
            current_hp: 30,
            max_hp: 30,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::ShrinkerBeetle),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: crate::MonsterId("ShrinkerBeetle"),
            ai: None,
        });
        state.enemy_uids.push(CreatureUid::new(30).unwrap());

        dispatch_before_turn_end(&mut state, &TurnSideCtx { side: Side::Player });

        let alive_hp = state
            .creatures
            .iter()
            .find(|c| c.id == alive_id)
            .map(|c| c.current_hp)
            .expect("alive enemy present");
        assert_eq!(
            alive_hp, 30,
            "Hailstorm must NOT fire when there is no Frost orb in the belt",
        );
    }

