    /// Bead `sts2-rs-r2ixj`: the `after_side_turn_start` walk must SKIP the
    /// folded `AfterPlayerTurnStart` powers (Inferno / Loop / SummonNextTurn /
    /// CrimsonMantle) — they are dispatched in the auto-play cluster instead.
    /// If the walk still fired Inferno, a Mayhem-auto-played Inferno (applied
    /// after the pre-auto-play snapshot, so present in the walk's live listener
    /// set) would self-damage this turn, which C#'s `AfterPlayerTurnStart`
    /// snapshot excludes (the seed-1130 over-fire).
    #[test]
    fn after_side_turn_start_walk_skips_folded_inferno() {
        let mut state = CombatState::default();
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let _player_uid = state.init_player_creature();

        let uid = power_uid(1);
        let mut pow = Power::new(uid.0, PowerKind::Inferno, 6);
        pow.counter = 2;
        state.powers.push(pow);
        state.player.powers.push(uid);

        // The post-cluster walk must NOT fire Inferno's self-damage.
        dispatch_after_side_turn_start(&mut state, &TurnSideCtx { side: Side::Player });

        assert_eq!(
            state.player.current_hp, 50,
            "after_side_turn_start walk must skip Inferno (cluster dispatches it)",
        );
    }

    /// **Inferno counterattack**: when the owner takes unblocked damage
    /// on the owner's own turn, deal `amount` UNPOWERED damage to every
    /// alive enemy. Python pin
    /// `remaining_b.py::InfernoPower.after_damage_received` (lines
    /// 468-484).
    #[test]
    fn inferno_counterattack_fires_on_own_turn_unblocked_damage() {
        let (mut state, enemy_ref) = state_with_enemy_power(PowerKind::Ritual, 0);
        let CreatureRef::Enemy(enemy_uid) = enemy_ref else {
            panic!("state_with_enemy_power returns Enemy ref");
        };
        // Add the player + a real player creature so the Inferno arm
        // can resolve `owner == Player` via the listener walk.
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        state.init_player_creature();
        state.side = Side::Player;

        // Inferno(6) on the player.
        let inferno_uid = power_uid(2);
        state
            .powers
            .push(Power::new(inferno_uid.0, PowerKind::Inferno, 6));
        state.player.powers.push(inferno_uid);

        let enemy_hp_before = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .map(|c| c.current_hp)
            .expect("enemy creature present");

        // Synthesize a "player took 5 unblocked damage on own turn" event.
        let ctx = DamageCtx {
            dealer: enemy_ref,
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        dispatch_after_damage_received(&mut state, &ctx, 5);

        // Inferno(6) UNPOWERED damage to enemy. ShrinkerBeetle has no
        // Vulnerable / Strength so post-pipeline damage == 6.
        let enemy_hp_after = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .map(|c| c.current_hp)
            .expect("enemy creature still present");
        assert_eq!(
            enemy_hp_before - enemy_hp_after,
            6,
            "Inferno counterattack must deal `amount` damage to each enemy",
        );
    }

    /// **Inferno mirror-power regression (q6bix card:INFERNO_CARD)** — the
    /// fan-out must resolve the Inferno stack via the mirror+legacy union
    /// (`player_power_amount`), NOT the raw `state.player.powers` surface.
    /// Card-driven `apply_power_to_creature` writes ONLY the mirror creature
    /// (`state.creatures[player_uid].powers`); the prior raw read missed it,
    /// so the +6-to-all-enemies reaction never fired in real combat. This
    /// test applies Inferno THROUGH the mirror and asserts each alive enemy
    /// loses 6 HP — it fails on HEAD (0 reactions) and passes after the swap.
    #[test]
    fn inferno_counterattack_resolves_mirror_applied_power() {
        let (mut state, enemy_ref) = state_with_enemy_power(PowerKind::Ritual, 0);
        let CreatureRef::Enemy(enemy_uid) = enemy_ref else {
            panic!("state_with_enemy_power returns Enemy ref");
        };
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        state.init_player_creature();
        state.side = Side::Player;

        // Apply Inferno(6) through the MIRROR creature (the card path),
        // not `state.player.powers.push`.
        let puid = state.player.creature_uid.unwrap();
        crate::card_effects::apply_power_to_creature(&mut state, puid, PowerKind::Inferno, 6);

        let enemy_hp_before = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .map(|c| c.current_hp)
            .expect("enemy creature present");

        let ctx = DamageCtx {
            dealer: enemy_ref,
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        dispatch_after_damage_received(&mut state, &ctx, 5);

        let enemy_hp_after = state
            .creatures
            .iter()
            .find(|c| c.id == enemy_uid.0)
            .map(|c| c.current_hp)
            .expect("enemy creature still present");
        assert_eq!(
            enemy_hp_before - enemy_hp_after,
            6,
            "mirror-applied Inferno(6) must fan 6 UNPOWERED damage to each enemy",
        );
    }

    /// **TaintedPower.ModifyDamageAdditive (`…wb8lk.4`)** — C# v0.107.1
    /// `TaintedPower.cs:18-30`: a Tainted power on the owner adds `Amount` to a
    /// POWERED attack whose TARGET is the owner — and ONLY then. An unpowered
    /// attack, or a powered attack against a different creature, gets nothing.
    #[test]
    fn tainted_adds_damage_to_powered_attack_vs_owner_only() {
        let mut state = CombatState::default();
        let pid = power_uid(1);
        state.powers.push(Power {
            id: pid.0,
            kind: PowerKind::Tainted,
            amount: 3,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(pid);
        let listener = ListenerRef::Power(pid);
        let other = CreatureRef::Enemy(CreatureUid::new(2).unwrap());

        // Powered enemy attack whose target IS the owner (player) → +Amount.
        let ctx_owner = DamageCtx {
            dealer: other,
            target: CreatureRef::Player,
            props: ValueProps::MOVE,
        };
        assert_eq!(
            modify_damage_additive(&state, listener, &ctx_owner),
            3,
            "powered attack vs the Tainted owner adds Amount"
        );

        // Unpowered attack vs the owner → 0.
        let ctx_unpowered = DamageCtx {
            dealer: other,
            target: CreatureRef::Player,
            props: ValueProps::MOVE.union(ValueProps::UNPOWERED),
        };
        assert_eq!(
            modify_damage_additive(&state, listener, &ctx_unpowered),
            0,
            "unpowered attack adds nothing"
        );

        // Powered attack vs a DIFFERENT target (not the owner) → 0.
        let ctx_other = DamageCtx {
            dealer: CreatureRef::Player,
            target: other,
            props: ValueProps::MOVE,
        };
        assert_eq!(
            modify_damage_additive(&state, listener, &ctx_other),
            0,
            "powered attack against a non-owner target adds nothing"
        );
    }

    /// **TaintedPower.AfterSideTurnEnd (`…wb8lk.4`)** — C# v0.107.1
    /// `TaintedPower.cs:32-39`: Tainted sits on the PLAYER but removes at the
    /// ENEMY's turn end (`side == CombatSide.Enemy`), NOT the owner's. So it
    /// survives the player's turn end and is removed at the enemy's turn end.
    #[test]
    fn tainted_removed_after_enemy_turn_not_player_turn() {
        let mut state = CombatState::default();
        let pid = power_uid(1);
        state.powers.push(Power {
            id: pid.0,
            kind: PowerKind::Tainted,
            amount: 3,
            counter: 0,
            applier: None,
            skip_next_tick: false,
        });
        state.player.powers.push(pid);

        // Player turn end: Tainted survives (removes only at the enemy turn end).
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Player });
        assert!(
            state.powers.iter().any(|p| p.id == pid.0),
            "Tainted must survive the player's turn end"
        );

        // Enemy turn end: removed.
        dispatch_after_turn_end(&mut state, &TurnSideCtx { side: Side::Enemy });
        assert!(
            !state.powers.iter().any(|p| p.id == pid.0),
            "Tainted must be removed at the enemy's turn end"
        );
    }

    /// **VitalSpark.AfterCardPlayed (`…wb8lk.4`)** — C# v0.107.1: playing a card
    /// whose affliction is Tainted makes each enemy VitalSpark stack
    /// `TaintedPower(Amount)` onto the player.
    #[test]
    fn vital_spark_stacks_tainted_on_player_when_tainted_card_played() {
        use crate::card_afflictions::{CardAffliction, CardAfflictionKind};
        let (mut state, _enemy) = state_with_enemy_power(PowerKind::VitalSpark, 3);
        // The player needs a mirror Creature for `apply_power_to_creature`.
        state.player.current_hp = 50;
        state.player.max_hp = 50;
        let player_uid = state.init_player_creature();

        // A Tainted Skill card at uid 1 (state.cards is indexed by uid - 1).
        state.cards.push(crate::cards::Card {
            uid: CardUid::new(1).unwrap(),
            card_type: crate::cards::CardType::Skill,
            affliction: Some(CardAffliction::new(CardAfflictionKind::Tainted, 3)),
            ..crate::cards::Card::pod_defaults()
        });

        let ctx = CardCtx {
            card_uid: Some(CardUid::new(1).unwrap()),
            card_type: Some(crate::cards::CardType::Skill),
            ..CardCtx::default()
        };
        dispatch_after_card_played(&mut state, &ctx);

        let tainted_on_player: i32 = state
            .creatures
            .iter()
            .find(|c| c.id == player_uid.0)
            .map_or(0, |c| {
                c.powers
                    .iter()
                    .filter_map(|pu| {
                        state
                            .powers
                            .iter()
                            .find(|p| p.id == pu.0 && p.kind == PowerKind::Tainted)
                            .map(|p| p.amount)
                    })
                    .sum()
            });
        assert_eq!(
            tainted_on_player, 3,
            "playing a Tainted Skill stacks TaintedPower(3) on the player"
        );
    }

    /// **VitalSpark.BeforeCombatStart (`…wb8lk.4`)** — C# v0.107.1: at combat
    /// start, VitalSpark taints every ally **Skill** card with Tainted(Amount);
    /// non-Skill cards (Attack/Power) are left untouched (the Skill-only
    /// `CanAfflictCardType` filter).
    #[test]
    fn vital_spark_before_combat_start_taints_only_skill_cards() {
        use crate::card_afflictions::CardAfflictionKind;
        let (mut state, _enemy) = state_with_enemy_power(PowerKind::VitalSpark, 3);

        // uid 1 = Skill (should be tainted), uid 2 = Attack (should NOT be).
        state.cards.push(crate::cards::Card {
            uid: CardUid::new(1).unwrap(),
            card_type: crate::cards::CardType::Skill,
            ..crate::cards::Card::pod_defaults()
        });
        state.cards.push(crate::cards::Card {
            uid: CardUid::new(2).unwrap(),
            card_type: crate::cards::CardType::Attack,
            ..crate::cards::Card::pod_defaults()
        });
        state.player.draw.push(CardUid::new(1).unwrap());
        state.player.draw.push(CardUid::new(2).unwrap());

        crate::monster_power_effects::vital_spark_before_combat_start(&mut state);

        assert!(
            matches!(
                state.cards[0].affliction,
                Some(crate::card_afflictions::CardAffliction {
                    kind: CardAfflictionKind::Tainted,
                    stacks: 3,
                    ..
                })
            ),
            "the Skill card must be tainted with Tainted(3)"
        );
        assert!(
            state.cards[1].affliction.is_none(),
            "the Attack card must NOT be tainted (Skill-only)"
        );
    }

