    /// The four `dispatch_after_card_played` lane masks, handled by their own
    /// structural test below (the dispatcher is a sequence of inline lanes,
    /// not a single per-listener `match`).
    const AFTER_CARD_PLAYED_MASKS: &[&str] = &[
        "AFTER_CARD_PLAYED_PLAYER_REACT_KINDS",
        "AFTER_CARD_PLAYED_PENDING_KINDS",
        "AFTER_CARD_PLAYED_SNAPSHOT_KINDS",
        "AFTER_CARD_PLAYED_ORDERED_ENEMY_HIT_KINDS",
    ];

    /// Kinds `dispatch_after_card_played` only ever APPLIES to a creature
    /// (arguments to `apply_power_to_creature` / `apply_signed_attr_power`:
    /// Tender drains Strength/Dexterity, Oblivion grants Doom, Enrage grants
    /// Strength) and never *discriminates* on. Mentioning an applied kind
    /// does not require gate coverage — the lane that applies it is gated on
    /// its own reactive kind. Keep this list minimal: a kind exempted here is
    /// invisible to the drift guard for this dispatcher.
    const AFTER_CARD_PLAYED_APPLIED_ONLY: PowerKindSet =
        PowerKindSet::from_kinds(&[PowerKind::Strength, PowerKind::Dexterity, PowerKind::Doom]);

    /// Strip `//` line comments and (nested) `/* */` block comments, and
    /// blank the interiors of string and char literals, so that a
    /// `PowerKind::Xxx` in prose or in a message string never counts as a
    /// mention and a `{`/`}` inside a literal never derails brace counting.
    /// Lifetime ticks (`'a`) are preserved.
    pub(super) fn sanitize(src: &str) -> String {
        let b = src.as_bytes();
        let mut out: Vec<u8> = Vec::with_capacity(b.len());
        let mut i = 0;
        while i < b.len() {
            match b[i] {
                b'"' => {
                    out.push(b'"');
                    i += 1;
                    while i < b.len() {
                        match b[i] {
                            b'\\' => {
                                out.extend_from_slice(b"  ");
                                i += 2;
                            }
                            b'"' => {
                                out.push(b'"');
                                i += 1;
                                break;
                            }
                            b'\n' => {
                                out.push(b'\n');
                                i += 1;
                            }
                            _ => {
                                out.push(b' ');
                                i += 1;
                            }
                        }
                    }
                }
                b'\'' => {
                    if i + 1 < b.len() && b[i + 1] == b'\\' {
                        // Escaped char literal: consume quote + backslash +
                        // escaped char, then blank to the closing quote
                        // (handles '\'' and '\u{..}').
                        out.extend_from_slice(b"   ");
                        i += 3;
                        while i < b.len() && b[i] != b'\'' {
                            out.push(b' ');
                            i += 1;
                        }
                        out.push(b' ');
                        i += 1;
                    } else if i + 2 < b.len() && b[i + 2] == b'\'' {
                        // Plain one-byte char literal 'x'.
                        out.extend_from_slice(b"   ");
                        i += 3;
                    } else {
                        // Lifetime tick.
                        out.push(b'\'');
                        i += 1;
                    }
                }
                b'/' if i + 1 < b.len() && b[i + 1] == b'/' => {
                    while i < b.len() && b[i] != b'\n' {
                        i += 1;
                    }
                }
                b'/' if i + 1 < b.len() && b[i + 1] == b'*' => {
                    let mut depth = 1;
                    i += 2;
                    while i < b.len() && depth > 0 {
                        if b[i] == b'/' && i + 1 < b.len() && b[i + 1] == b'*' {
                            depth += 1;
                            i += 2;
                        } else if b[i] == b'*' && i + 1 < b.len() && b[i + 1] == b'/' {
                            depth -= 1;
                            i += 2;
                        } else {
                            if b[i] == b'\n' {
                                out.push(b'\n');
                            }
                            i += 1;
                        }
                    }
                }
                c => {
                    out.push(c);
                    i += 1;
                }
            }
        }
        String::from_utf8(out).expect("sanitizer preserved UTF-8 validity")
    }

    /// Return the brace-balanced block starting at the first `{` of `s`.
    fn brace_matched(s: &str) -> &str {
        let open = s.find('{').expect("no opening brace");
        let mut depth = 0usize;
        for (off, c) in s[open..].char_indices() {
            match c {
                '{' => depth += 1,
                '}' => {
                    depth -= 1;
                    if depth == 0 {
                        return &s[open..=open + off];
                    }
                }
                _ => {}
            }
        }
        panic!("unbalanced braces");
    }

    /// Cut the body of `fn <name>(...) ... { ... }` out of the sanitized
    /// source. Panics if the fn is missing (renamed?) or defined twice.
    pub(super) fn fn_body<'a>(src: &'a str, name: &str) -> &'a str {
        let needle = format!("fn {name}(");
        let mut hits = src.match_indices(&needle);
        let (start, _) = hits.next().unwrap_or_else(|| {
            panic!(
                "listener fn `{name}` not found in hooks.rs — if it was renamed, \
                 update GATED_LISTENERS in the mask drift guard"
            )
        });
        assert!(
            hits.next().is_none(),
            "`{needle}` matches more than one definition — make the guard's \
             fn table unambiguous"
        );
        brace_matched(&src[start..])
    }

    /// Resolve a variant identifier (as written in source, `Xxx` of
    /// `PowerKind::Xxx`) to the actual enum value via its `Debug` name.
    fn kind_by_ident(ident: &str) -> PowerKind {
        // The v0.111.0-only kinds (GH #794) sit outside `all()`.
        PowerKind::all()
            .iter()
            .chain(PowerKind::V0111_ONLY.iter())
            .copied()
            .find(|k| format!("{k:?}") == ident)
            .unwrap_or_else(|| panic!("`PowerKind::{ident}` is not a known variant"))
    }

    /// Every `PowerKind::Xxx` token in `body` (comments/strings already
    /// stripped by [`sanitize`]).
    pub(super) fn kind_mentions(body: &str) -> Vec<PowerKind> {
        const TOKEN: &str = "PowerKind::";
        let mut out = Vec::new();
        let mut rest = body;
        while let Some(pos) = rest.find(TOKEN) {
            rest = &rest[pos + TOKEN.len()..];
            let ident: String = rest
                .chars()
                .take_while(|c| c.is_alphanumeric() || *c == '_')
                .collect();
            // `PowerKind::all()` etc. (lowercase assoc fns) are not variants.
            if ident.chars().next().is_some_and(char::is_uppercase) {
                out.push(kind_by_ident(&ident));
            }
        }
        out
    }

    /// The unique occurrence of `needle` in `body`, then the next
    /// brace-balanced block after it.
    fn block_after<'a>(body: &'a str, needle: &str) -> &'a str {
        let pos = body
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` not found in dispatcher body"));
        assert!(
            body[pos + needle.len()..].find(needle).is_none(),
            "`{needle}` is not unique in the dispatcher body — tighten the \
             needle in the mask drift guard"
        );
        brace_matched(&body[pos..])
    }

    /// Every `power_kind_live(state, PowerKind::K)` self-gate in `body`,
    /// paired with the brace-balanced block following the call (the lane it
    /// gates). Calls whose kind argument is not a literal `PowerKind::` path
    /// are skipped — skipping only makes the guard stricter (the kind then
    /// needs union-mask coverage instead of a self-gate exemption).
    fn self_gates(body: &str) -> Vec<(PowerKind, &str)> {
        const CALL: &str = "power_kind_live(";
        let mut out = Vec::new();
        let mut from = 0;
        while let Some(rel) = body[from..].find(CALL) {
            let args_start = from + rel + CALL.len();
            let mut depth = 1usize;
            let mut args_end = None;
            for (off, c) in body[args_start..].char_indices() {
                match c {
                    '(' => depth += 1,
                    ')' => {
                        depth -= 1;
                        if depth == 0 {
                            args_end = Some(args_start + off);
                            break;
                        }
                    }
                    _ => {}
                }
            }
            let args_end = args_end.expect("unbalanced parens in power_kind_live call");
            let args: String = body[args_start..args_end]
                .chars()
                .filter(|c| !c.is_whitespace())
                .collect();
            if let Some(ident) = args.strip_prefix("state,PowerKind::") {
                out.push((kind_by_ident(ident), brace_matched(&body[args_end..])));
            }
            from = args_end;
        }
        out
    }

    /// For every gated per-listener channel: each `PowerKind` the listener
    /// fn(s) mention must be in the gate mask, or the gate silently drops
    /// the kind's behavior whenever no *other* mask kind is live.
    #[test]
    fn per_listener_masks_cover_their_listener_fns() {
        let src = sanitize(SRC);
        for (mask_name, mask, fns) in GATED_LISTENERS {
            for fn_name in *fns {
                for kind in kind_mentions(fn_body(&src, fn_name)) {
                    assert!(
                        mask.contains(kind),
                        "MASK DRIFT: `{fn_name}` mentions PowerKind::{kind:?} but \
                         `{mask_name}` does not contain it — the gated dispatcher \
                         would silently skip that arm whenever no other mask kind \
                         is live. Add PowerKind::{kind:?} to {mask_name}."
                    );
                }
            }
        }
    }

    /// `dispatch_after_card_played` is a multi-lane dispatcher: an outer
    /// union mask gates the `player_power_uids` build, three sub-masks gate
    /// union-consuming passes, and arena-wide lanes self-gate with
    /// `power_kind_live`. Check each structural invariant.
    #[test]
    fn after_card_played_masks_cover_dispatcher_lanes() {
        let src = sanitize(SRC);
        // The dispatcher is split: the ordered enemy-hitting walk runs ahead
        // of the relic bus (`dispatch_after_card_played_ordered_enemy_hits`),
        // the other player lanes live in `dispatch_after_card_played_player_powers`
        // and the enemy / teammate lanes in
        // `dispatch_after_card_played_other_creatures`.
        let body_owned = format!(
            "{}\n{}\n{}",
            fn_body(&src, "dispatch_after_card_played_player_powers"),
            fn_body(&src, "dispatch_after_card_played_other_creatures"),
            fn_body(&src, "dispatch_after_card_played_ordered_enemy_hits")
        );
        let body = body_owned.as_str();
        let union = super::AFTER_CARD_PLAYED_PLAYER_REACT_KINDS;

        // (a) The per-pass sub-masks must be subsets of the outer union mask:
        // a kind present in a sub-mask but not the union would pass its pass
        // gate yet walk an EMPTY `player_power_uids` (the union gate skipped
        // the build) — silent no-op drift.
        for (sub_name, sub) in [
            (
                "AFTER_CARD_PLAYED_PENDING_KINDS",
                super::AFTER_CARD_PLAYED_PENDING_KINDS,
            ),
            (
                "AFTER_CARD_PLAYED_SNAPSHOT_KINDS",
                super::AFTER_CARD_PLAYED_SNAPSHOT_KINDS,
            ),
            (
                "AFTER_CARD_PLAYED_ORDERED_ENEMY_HIT_KINDS",
                super::AFTER_CARD_PLAYED_ORDERED_ENEMY_HIT_KINDS,
            ),
        ] {
            for &kind in PowerKind::all() {
                assert!(
                    !sub.contains(kind) || union.contains(kind),
                    "MASK DRIFT: {sub_name} contains PowerKind::{kind:?} but the \
                     outer AFTER_CARD_PLAYED_PLAYER_REACT_KINDS union does not — \
                     the sub-gated pass would walk an empty uid list."
                );
            }
        }

        // (b) Each sub-gated region only discriminates on kinds its sub-mask
        // contains. The pending/snapshot passes are the if-blocks right after
        // their `intersects(&…)` gates; the ordered walk is the for-loop over
        // the gate-assigned `ordered_walk_uids` binding.
        for (sub_name, sub, needle) in [
            (
                "AFTER_CARD_PLAYED_PENDING_KINDS",
                super::AFTER_CARD_PLAYED_PENDING_KINDS,
                "intersects(&AFTER_CARD_PLAYED_PENDING_KINDS)",
            ),
            (
                "AFTER_CARD_PLAYED_SNAPSHOT_KINDS",
                super::AFTER_CARD_PLAYED_SNAPSHOT_KINDS,
                "intersects(&AFTER_CARD_PLAYED_SNAPSHOT_KINDS)",
            ),
            (
                "AFTER_CARD_PLAYED_ORDERED_ENEMY_HIT_KINDS",
                super::AFTER_CARD_PLAYED_ORDERED_ENEMY_HIT_KINDS,
                "for uid in ordered_walk_uids",
            ),
        ] {
            for kind in kind_mentions(block_after(body, needle)) {
                assert!(
                    sub.contains(kind),
                    "MASK DRIFT: the pass gated by `{needle}` mentions \
                     PowerKind::{kind:?} but {sub_name} does not contain it."
                );
            }
        }

        // (c) A self-gated lane that consumes `player_power_uids` still
        // depends on the outer union gate having built the list: its kind
        // must ALSO be in the union mask (Afterimage / Juggling / Tender /
        // Monologue today). Arena-walking self-gated lanes (Slow / Enrage /
        // Oblivion / Strangle / Galvanic / CurlUp / …) don't touch the list
        // and need no union coverage.
        let gates = self_gates(body);
        assert!(
            !gates.is_empty(),
            "expected power_kind_live self-gates in dispatch_after_card_played — \
             did the lane-gating shape change? Update the mask drift guard."
        );
        let mut self_gated: Vec<PowerKind> = Vec::new();
        for &(kind, lane) in &gates {
            self_gated.push(kind);
            if lane.contains("player_power_uids") {
                assert!(
                    union.contains(kind),
                    "MASK DRIFT: the power_kind_live(PowerKind::{kind:?}) lane \
                     consumes player_power_uids, so the kind must also be in \
                     AFTER_CARD_PLAYED_PLAYER_REACT_KINDS (or the union gate \
                     skips the uid build and the lane walks an empty list)."
                );
            }
        }

        // (d) Completeness: every kind the dispatcher body mentions must be
        // accounted for — in the union mask, self-gated by power_kind_live,
        // or on the documented applied-only list. A brand-new inline lane
        // that discriminates on an unlisted kind fails here.
        for kind in kind_mentions(body) {
            assert!(
                union.contains(kind)
                    || self_gated.contains(&kind)
                    || AFTER_CARD_PLAYED_APPLIED_ONLY.contains(kind),
                "MASK DRIFT: dispatch_after_card_played mentions \
                 PowerKind::{kind:?} but it is neither in \
                 AFTER_CARD_PLAYED_PLAYER_REACT_KINDS, nor self-gated via \
                 power_kind_live, nor on the applied-only exemption list — \
                 gate the new lane or extend the masks."
            );
        }
    }

    /// The names of the `PowerKindSet` consts declared in `src` whose name
    /// ends in `suffix`, sorted.
    fn declared_kind_set_consts(src: &str, suffix: &str) -> Vec<String> {
        let mut declared: Vec<String> = Vec::new();
        let mut from = 0;
        while let Some(rel) = src[from..].find("const ") {
            let ident_start = from + rel + "const ".len();
            let ident: String = src[ident_start..]
                .chars()
                .take_while(|c| c.is_alphanumeric() || *c == '_')
                .collect();
            from = ident_start + ident.len().max(1);
            if !ident.ends_with(suffix) {
                continue;
            }
            let after: String = src[from..]
                .chars()
                .take(64)
                .filter(|c| !c.is_whitespace())
                .collect();
            if after.starts_with(":crate::PowerKindSet") || after.starts_with(":PowerKindSet") {
                declared.push(ident);
            }
        }
        declared.sort_unstable();
        declared
    }

    /// Completeness sweep: every `*_KINDS: PowerKindSet` mask const declared
    /// in this file must be registered with this guard (either in
    /// `GATED_LISTENERS` or as one of the four after-card-played lane masks).
    /// Adding a new gated channel without teaching the guard about it fails
    /// here.
    #[test]
    fn every_mask_const_is_covered_by_this_guard() {
        let declared = declared_kind_set_consts(&sanitize(SRC), "_KINDS");
        let mut covered: Vec<String> = GATED_LISTENERS
            .iter()
            .map(|(name, _, _)| (*name).to_string())
            .chain(AFTER_CARD_PLAYED_MASKS.iter().map(|s| (*s).to_string()))
            .collect();
        covered.sort_unstable();
        assert_eq!(
            declared, covered,
            "the set of `*_KINDS: PowerKindSet` consts in hooks.rs no longer \
             matches the masks registered with the drift guard — register the \
             new mask (left: declared in file, right: covered by guard)"
        );
    }

